    ["Disguised as one of Akama's Ashtongue Broken."] = "아카마의 잿빛혓바닥 결사단 드레나이 모습으로 변신 중",
    ["Next spell casts in half the normal time."] = "다음 주문의 시전 시간 절반만큼 단축",
    ["Movement speed reduced by $s1%.\nAll attributes reduced by $s2%."] = "이동 속도 $s1%만큼 감소모든 능력치 $s2%만큼 감소",
    ["You feel good."] = "기분이 좋습니다.",
    ["Ignored."] = "무시됨",
    ["The bogblossom has exploded, spraying pollen everywhere!"] = "수렁꽃이 사방으로 꽃가루를 날리며 터집니다.",
    ["Teleport player to the Shade of Aran's room."] = "플레이어를 아란의 망령의 방으로 순간이동 시킵니다.",
    ["Enraged.\nCharging random enemy targets."] = "광포해짐무작위로 적 대상에 돌진",
    ["Heals the pet and master for $s1% of their total health per second."] = "소환수와 그 주인은 매초마다 최대 생명력의 $s1%만큼 회복",
    ["Melee, casting and ranged attacks slowed by $s1%."] = "근접, 원거리 공격 및 주문 시전 속도 $s1%만큼 감소",
    ["The spirit of Clintar Dreamwalker has drawn you into the limbo between the Emerald Dream and the waking world. You will not be able to make contact with Clintar's spirit again until you've emerged from this state."] =
    "클린타르 드림워커의 영혼이 당신을 에메랄드의 꿈과 현실 세계의 중간계로 인도했습니다. 이 상태를 벗어나기 전까지는 클린타르의 영혼과 함께 하는 어떠한 임무도 다시 시작할 수 없습니다.",
    ["Heals for $$s1s$s2 the next time you take damage."] = "다음 피해 입을 시 $$s1s$s2의 생명력 회복",
    ["Increases maximum health by $s1 and restores $s2 health every $s3 seconds  Guardian Elixir."] =
    "최대 생명력이 $s1만큼 증가매 $s3초당 $s2의 생명력 회복강화 비약",
    ["Prevents up to $s1 damage done by a physical or magical attack.  Guardian Elixir."] = "최대 $s1의 물리 또는 마법 피해 방지강화 비약",
    ["Increases Resilience Rating by $s1 for $d.   Guardian Elixir."] = "$d 동안 탄력도 $s1만큼 증가강화 비약",
    ["Unable to move or use abilities.\nPeriodically inflicting Shadow damage to nearby enemies."] =
    "이동 및 능력 사용 불가주기적으로 주위 적에게 암흑 피해",
    ["$h% chance to heal enemy target on spell or melee hit."] = "주문 및 근접 공격 시 $h%의 확률로 대상 치유",
    ["$s1 Nature damage inflicted every $t$s2 sec.\nDamage taken increased by $s3%\n"] =
    "매 $t$s2초마다 $s1의 자연 피해받는 피해 $s3%만큼 증가",
    ["You possess aether sight, allowing you to see spirits with a strong affinity to the physical world, but inflicting periodic damage."] =
    "에테르 시야를 통해 물리 세계와 강한 결합력을 가진 영혼을 볼 수 있지만 주기적인 물리 피해를 입습니다.",
    ["The magic augmenting your sight has transformed you, causing you to appear as Sai'kkal the Elder's student, Rokkaram."] =
