    ["All damage dealt is increased by $s1%.\nAttack speed increased by $s2%."] = "모든 공격력 $s1%만큼 증가공격 속도 $s2%만큼 증가",
    ["Inflicts Frost damage to players within $A$s1 yards of the Ice Spear!"] = "주위 $A$s1미터 반경에 있는 플레이어에게 냉기 피해",
