    ["Bleed effects cause an additional $s1% damage."] = "출혈 효과로 $s1%의 추가 피해",
    ["Teleport player to Apex Point."] = "태양 향점으로 순간이동",
    ["Casts Hailstone Chill on nearby players."] = "주변 플레이어에게 으스스한 우박 시전",
    ["Your next Slam is instant."] = "다음 격돌은 즉시 시전",
    ["You cannot be stopped and perform a Whirlwind every $t$s1 sec.  No other abilities can be used."] =
