    ["That was cold, but it went down smooth."] = "차갑지만 부드럽게 넘어갑니다.",
    ["Chance to be hit by all attacks and spells reduced by $s1%."] = "모든 공격과 주문에 적중 당할 확률 $s1%만큼 감소",
    ["You feel strong enough to hurl boulders!"] = "바위를 날려버릴 만큼 힘이 세졌습니다!",
    ["You have Budd's undivided attention... for now."] = "일에 전념하는 버드가 당신을 따릅니다... 당분간 말입니다.",
