    "악마 형상장비 착용으로 인한 방어도 $$s1s$s2%만큼 증가치명타에 적중 당할 확률 $s3%만큼 감소공격력 $$s1s$s4%만큼 증가기절과 감속 효과의 지속시간 $$s5s$s6%만큼 감소",
