    ["Resurrects all fallen allies within view."] = "시야에 보이는 쓰러진 아군을 모두 부활시킵니다.",
    ["Damage and size increased."] = "공격력 및 크기 증가",
    ["Incinerate - Increases damage done by $$s1s$s2% and reduces cast time by $$s1s$s3%.\n\nSoul Fire - Increases damage done by $$s1s$s2% and increases critical strike chance by $$s1s$s4%."] =
    "소각 - 공격력 $$s1s$s2%만큼 증가, 시전 시간 $$s1s$s3%만큼 감소영혼의 불꽃 - 공격력 $$s1s$s2%만큼, 극대화 적중률 $$s1s$s4%만큼 증가",
    ["The magical energies are being redirected and repurposed by the mage hunter forces."] =
