    ["Frozen solid."] = "단단한 얼음",
    ["Movement slowed by $s1%.  $s2 Fire damage every $t$s3 sec."] = "이동 속도 $s1%만큼 감소매 $t$s3초마다 $s2의 냉기화염 피해",
