    ["The Horde Siege Tank can move faster thanks to the rescued engineer!"] = "구출된 기술자 덕분에 호드 공성 전차가 더 빠르게 웁직입니다!",
    ["Bloodied."] = "피에 젖음",
    ["Protected by the injured Warsong warrior. Armor increased by $s1%!"] = "부상당한 전쟁노래부족 전사에게 보호받고 있습니다.방어도 $s1%만큼 증가",
    ["Demonic Circle Summoned."] = "악마의 마법진 소환",
    ["Increases ground speed by $s1%. Increases flying speed by $s2%."] = "이동 속도 $s1%만큼 증가비행 속도 $s2%만큼 증가",
    ["You're immune!"] = "면역입니다.",
    ["Increases armor by $s1 and spell power by $s2."] = "방어도 $s1만큼 증가주문력 $s2만큼 증가",
