    ["Damage taken from Shadow damage-over-time effects increased by $s1%."] = "암흑 계열의 주기적인 효과로 인한 피해 $s1%만큼 증가",
    ["A Healer has stricken you.  $s1 strikes and you're out!"] = "치유사에게 공격을 당했습니다. $s1회 공격 당하면 끝입니다.",
