    ["Damage equal to $s1% of maximum health inflicted every $t$s2 sec."] = "매 $t$s2초마다 최대 생명력의 $s1%에 해당하는 피해",
    ["Chance for an enemy to dodge reduced by $s1%.\nPhysical damage taken is increased by $s2%."] =
