    ["Flight Form and Swift Flight Form speed increased by $s1%."] = "폭풍까마귀와 빠른 폭풍까마귀 변신 시 비행 속도 $s1%만큼 증가",
    ["Immobilized.\nInflicts $$s1s$s2 Fire damage to nearby enemies after $d."] = "이동 불가주위 적에게 $d 후 $$s1s$s2의 화염 피해",
