    "불꽃인도자가 기수를 떨쳐내려 합니다. 위험을 감수해야 하거나 볼드룬으로 돌아가야 합니다.",
    ["Unstoppable.\nIncreases movement speed by $s1%.\nIncreases damage by $s2%.\nStunned for $$s3d when effect ends."] =
    "저지 불가이동 속도 $s1%만큼 증가공격력 $s2%만큼 증가효과가 사라지면 $$s3d 동안 기절",
    ["Spell damage reduced by $s1%.\nImmune to magic debuffs."] = "주문 피해 $s1%만큼 감소마법 약화 효과에 면역",
    ["Will denounce the Scarlet Onslaught before he dies!"] = "죽기 전에 붉은돌격대를 비난할 것입니다!",
    ["A rope leash."] = "소환수 목줄입니다.",
    ["Image being absorbed for duplication."] = "복제할 대상의 환영 흡수",
    ["Appears identical to a Burning Depths Necrolyte.  This spell will be removed by combat."] =
    "불타는 심연 강령사로 위장전투 시작 시 제거됨",
    ["Certain to fool the Scarlet Onslaught. Must stay within New Hearthglen or the image will be lost!"] =
    "붉은돌격대를 속일 수 있습니다.신 하스글렌을 벗어나면 환영이 사라집니다!",
    ["Serinar sees through your eyes..."] = "세린나가 당신의 눈을 통해 사물을 봅니다.",
    ["Damage taken reduced.\nImmune to Stun effects."] = "받는 피해 감소기절에 면역",
    ["Spirit form. This effect only functions at the Forgotten Shore."] = "영혼 형태망각의 해변에서만 효과",
    ["Your Shock spells have a chance to grant you $$s1s$s2 attack power for $$s1d."] =
    "충격 계열 주문 사용 시 일정 확률로 $$s1d 동안 전투력이 $$s1s$s2만큼 증가합니다.",
    ["Damage done by attacks and spells reduced by $s1."] = "공격력 $s1만큼 감소",
    ["Deals a vengeful blow, instantly killing the target."] = "복수의 이빨로 대상을 물어뜯어 즉사시킵니다.",
    ["Deals $$s1s$s2 Shadow damage to nearby friends after $t$s3 sec."] = "$t$s3초 후 주위 아군에게 $$s1s$s2의 암흑 피해",
    ["Friend to the ghosts of the Forgotten Shore."] = "망각의 해변의 유령에 우호적인 상태입니다.",
    ["Places Orik's orb at the center of the ruins found at the Forgotten Shore."] =
    "망각의 해변에서 찾을 수 있는 폐허의 중앙에 오리크의 구슬을 놓기",
    ["Decreases healing received by $s1%."] = "받는 치유 효과 $s1%만큼 감소",
    ["Deals $$s1s$s2 damage when damaged by Beasts."] = "야수에게 피해를 받으면 $$s1s$s2의 피해",
    ["Redeemed."] = "구원됨",
    ["Hit rating increased by $s1."] = "적중도 $s1만큼 증가",
    ["Physical damage inflicted every $t$s1 sec.\nYou will bleed until fully healed."] =
    "매 $t$s1초마다 물리 피해생명력이 모두 회복될 때까지 출혈",
    ["You have been marked for death by Thel'zan the Duskbringer. Deliver the tome to Cavalier Durkon before you are killed!"] =
    "황혼의 인도자 텔잔에게 죽음의 표적이 되었습니다. 죽기 전에 기병 드류콘에게 고서를 가져가야 합니다!",
    ["Hits by this target restore $s1% health."] = "공격 적중 시 대상의 생명력 $s1%만큼 회복",
    ["Your smile is simply dazzling."] = "눈부신 미소",
    ["Enraged.\nPhysical damage increased by $s1%.\nHealth equal to $s2% of maximum health lost every sec."] =
    "격노함. 물리 공격력 $s1%만큼 증가매초마다 최대 생명력의 $s2%만큼 피해",
    ["Deals $s1 Nature damage every $t$s2 sec.\nAttributes reduced by $s3%."] = "매 $t$s2초마다 $s1의 자연 피해능력치 $s3%만큼 감소",
    ["You have recently summoned a rune weapon."] = "최근 룬 무기 소환함.",
    ["Fixated.\nAttack speed increased by $s1%."] = "시전 집중됨공격 속도 $s1%만큼 증가",
    ["Frost damage inflicted every $t$s1 sec."] = "매 $t$s1초마다 냉기 피해",
    ["Immune to Charm, Fear and Sleep.\nUndead."] = "현혹, 공포, 수면에 면역언데드",
    ["Ejects the master from the vehicle inflicting $s1 damage."] = "탈것에서 주인을 밀쳐내고 $s1의 피해를 입힙니다.",
    ["Controlling an Alliance Steam Tank! You may only drive the tank within the boundaries of the Carrion Fields."] =
    "얼라이언스 증기 전차 조종 중부패의 벌판에서만 사용 가능",
    ["Your consciousness is projected to a far-away land."] = "아주 멀리 떨어진 곳으로 영혼이 투사됩니다.",
    ["Attack speed increased by $s1%.\nApplied Shred to target when meleed."] = "공격 속도 $s1%만큼 증가근접 공격 시 대상에게 칼날 발톱 효과 유발",
    ["Base movement speed cannot be increased. Damage done to you is increased by $s1%. Prevents stealth and invisibility."] =
    "기본 이동 속도가 증가하지 않습니다. 자신이 받는 피해가 $s1%만큼 증가합니다. 은신과 투명화를 방지합니다.",
    ["Turning into a Wolf Spirit."] = "늑대 정령으로 변신",
    ["Transformed into an unstoppable Wolf Spirit.\nIncreased melee damage and attack speed.\nUnable to cast spells."] =
    "저지할 수 없는 늑대 정령으로 변신근접 공격력 및 공격 속도 증가주문 시전 불가",
    ["Time remaining until warhead detonation."] = "탄두 폭발까지 남은 시간",
    ["Taking damage from a vile swarm of unholy insects.  Diseases cannot be dispelled."] = "부정의 벌레떼의 공격질병 무효화 불가",
    ["Under attack from a Gargoyle."] = "가고일에게 공격당함.",
    ["This vehicle will self-destruct in $s1 seconds."] = "$s1초 후에 자폭합니다.",
    ["Controlling a Wyrmrest Defender! You may only fly in Wyrmrest Temple, the Dragon Wastes, Azure Dragonshrine, the Path of the Titans, or the Mirror of Dawn."] =
    "고룡쉼터 사원 파수꾼을 조종합니다!고룡쉼터 사원, 용의 황무지, 청금석 용제단, 티탄의 길, 새벽의 거울에서만 비행 가능",
    ["Damage healed $s1% every $t$s2 sec."] = "매 $t$s2초마다 용의 생명력 $s1%만큼 회복",
    ["Tempted by wild carrots."] = "야생 당근으로 유혹",
    ["Riding a Highland Mustang. Return it to Squire Percy at the Westfall Brigade Encampment."] =
    "산악 야생마를 몰고 있습니다.서부 몰락지대 여단 야영지에 있는 종자 퍼시에게 데려가십시오.",
    ["Spirit based mana regeneration increased by $s1%.  Full mana regeneration while casting."] =
    "정신력을 기반으로 마나 회복 속도 $s1%만큼 증가시전 중 평상시 속도로 마나 회복",
    ["Attempting to tame the wild Shoveltusk"] = "야생 뾰족엄니 길들이기",
    ["You cannot currently ask for a wyrmrest defender to be called down."] = "지금은 고룡쉼터 사원 파수꾼을 불러내릴 수 없습니다.",
    ["Slowed down by the freezing blast."] = "얼음 폭격으로 느려짐",
    ["Imprisoned in ice."] = "얼음에 갇힘",
    ["Use your Racer's Slam to destroy other Crashin' Thrasin' Racers."] = "다른 우당탕 쿠당탕 자동차를 향해 돌진하세요.",
    ["You feel your flesh melting away...."] = "살이 녹는 것 같습니다...",
    ["The magic of the Ruby Acorn returns the dragon to the earth and nourishes the land with it's essence..."] =
