    "매 $t$s1초마다 암흑 피해생명력이 $s2% 밑으로 떨어지면 효과 사라짐",
    ["HELP!"] = "사람 살려!",
    ["Controlling a $s1th Legion chain gun!"] = "$s1군단 대포 조종 중",
    ["All Damage taken is increased by $s1%.\nEvery $s2,$s3 Damage taken generates a Shock Charge."] =
    "받는 모든 피해 $s1%만큼 증가$s2,$s3의 피해를 받으면 충격 충전",
    ["Deliver the gryphon to Uzo Deathcaller at Death's Rise.  Can only be ridden within Icecrown."] =
