    ["Runic power that increases size and increases attack power by $s1."] = "룬의 마력으로 거대화되어 힘이 $s1만큼 증가합니다.",
    ["After $s1 seconds inflicts $$s2s$s3 Nature damage and $$s2s$s4 Nature damage every $s4 sec.\nThe ground beneath you begins to crack."] =
    "$s1초 후 $$s2s$s3의 자연 피해매 $s4초마다 $$s2s$s4의 자연 피해땅에 균열 발생",
    ["Deals $s1 nature damage per second."] = "매초마다 $s1의 자연 피해",
    ["Increases physical damage done by $s1."] = "물리 공격력 $s1만큼 증가",
