    ["Immobilized.\nTime between attacks increased by $s1%.\nCasting speed decreased by $s1%."] =
    "이동 불가공격 간격 $s1%만큼 늘어남시전 속도 $s1%만큼 감소",
    ["Attacks deal additional Shadow damage every $$s1t$s2 sec."] = "매 $$s1t$s2초마다 추가 암흑 피해",
    ["Imprinted with minor rune power that increases attack and cast speed by $s1% for $d."] =
    "룬 마력의 영향으로 $d 동안 공격 속도와 시전 속도가 $s1%만큼 증가합니다.",
    ["All damage taken reduced by up to $s1."] = "받는 모든 피해 최대 $s1만큼 감소",
