    ["Your next Icy Touch, Howling Blast, Frost Strike or Obliterate has a $s1% chance to critically hit."] =
    "다음 시전하는 얼음 손길, 작렬하는 분노, 냉기의 일격, 절멸은 $s1%의 확률로 치명타로 적중",
    ["You are controlling an anti-air gun."] = "대공포 조종 중",
    ["Deals $s1 Shadow damage per sec."] = "매초마다 $s1의 암흑 피해",
    ["Activates Zelig's Scrying Orb at the bottom of Frostmourne Cavern."] = "서리한 동굴 깊숙한 곳에서 젤리그의 수정구 작동",
    ["Springtime is here!"] = "봄이 왔습니다!",
    ["Causing shadow damage to all targets within $a$s1 yards."] = "$a$s1미터 내에 있는 모든 대상에게 암흑 피해",
    ["You feel bloated."] = "부풀어 오르고 있습니다.",
    ["The bubble has grown."] = "거품이 커졌습니다.",
    ["Charge Level $s1 of $s2.\n$s3 temporal energy stored."] = "충전 단계 $s1/$s2충전된 임시 에너지 $s3",
    ["Frozen in time."] = "시간 속에 얼어붙음",
    ["Reduces all damage taken by $s1%.\nAfter $s2 stacks you become stunned for $$s3d."] =
    "받는 모든 피해 $s1%만큼 감소$s2번 중첩되면 $$s3d 동안 기절",
    ["Your mind has become perturbed for $d sec.\nStunned."] = "$d 동안 정신 불안기절함.",
    ["Drains $s1 health from an enemy, transferring it to the caster."] = "적으로부터 $s1의 생명력을 흡수하여 시전자에게로 이전",
    ["Now that's some Hustle!"] = "마무리할 시간입니다!",
    ["Controlling a Stone Giant with the Rune of Command."] = "지배의 룬으로 바위 거인 조종 중",
    ["Your nostrils have been assaulted."] = "코가 얼얼합니다.",
    ["There's no polite way to end this."] = "예의 바르게 마무리하는 건 불가능합니다.",
    ["Reduces chance to hit by $s1%."] = "적중률 $s1%만큼 감소",
    ["Your stomach is in upheaval. If only you could relieve your pain..."] = "위가 뒤집힙니다. 조금이라도 고통을 덜어낼 수만 있다면...",
    ["Covered in vomit."] = "토사물에 뒤덮힘",
