    ["An anti-air turret has locked onto you!"] = "대공 포탑의 조준을 받고 있습니다!",
    ["An Anti-Air Gun is attempting to lock onto you!"] = "대공포의 조준을 받고 있습니다!",
    ["Lead a parade in style."] = "화려한 거리 축제",
    ["Cursed.\nCute."] = "저주 걸림귀여운 외모",
    ["$s1 Shadow damage inflicted every sec"] = "매초마다 $s1의 암흑 피해",
    ["Inflicts $s1 Fire damage every $t$s2 sec."] = "매 $t$s2초마다 $s1의 화염 피해",
    ["Cannot be target locked."] = "조준 잠금 불가",
    ["Increases Fire damage taken by $s1%."] = "받는 화염 피해 $s1%만큼 증가",
    ["Welcome to the jungle, baby!"] = "여기가 정글입니다!",
    ["Hi Kyle, this spell worked!"] = "안녕, 카일주문 작동!",
    ["Immobilized.\n$o$s1 damage inflicted every $t$s1 sec."] = "이동 불가매 $t$s1초마다 $o$s1의 물리 피해",
    ["Increases damage done by $s1%.\nAfter $s2 stacks you become completely infected."] =
    "받는 피해 $s1%만큼 증가$s2번 중첩 후 완전히 감염됨",
    ["Firing machine gun.\nChance to hit reduced by $s1%."] = "기관총 발사적중률 $s1%만큼 감소",
    ["Controlling an Iron Rune Construct."] = "무쇠룬 피조물 조종 중",
    ["The cut on your hand enables you to make the blood oath with Drakuru."] = "손의 상처로 드라쿠루와 피의 서약을 맺습니다.",
    ["Allows the wearer to breathe under water. Must be within vision range of the buoy floating in Daggercap Bay."] =
    "물속에서 숨쉴 수 있도록 해줍니다. 비수집 만에 떠다니는 부표가 보이는 범위 내에 있어야 합니다.",
    ["Controlling a trained rock falcon!"] = "길들인 바위매 부리는 중",
    ["Soaring.  Flight speed and health regeneration increased.  This ability is only active out of combat."] =
    "활공비행 속도 및 생명력 회복 속도 증가전투 중이 아닐 때만 효과가 있음",
    ["Inflicts $s1 Nature damage every $$s2t$s3 sec."] = "매 $$s2t$s3초마다 $s1의 자연 피해",
    ["Drains health to the caster every $t$s1 sec."] = "매 $t$s1초마다 생명력 흡수",
    ["Shielded from damage.\nThis shield is powered by Centrifuge Constructs throughout the Oculus."] =
    "피해로부터 보호마력의 눈 원심력 피조물이 에너지 공급",
    ["Increased chance to Dodge by $s1%.\nIncreased chance to Parry by $s2%."] = "회피 확률 $s1%만큼 증가무기 막기 확률 $s2%만큼 증가",
    ["Your stomach is strong!  You are feeling much better now."] = "당신의 위는 튼튼합니다! 한결 편안하군요.",
    ["Warning, you and your wyrmrest defender have left the designated combat area."] = "지정 전투 지역을 벗어났습니다.",
    ["Increases Physical damage taken by $s1 for $d.\nStacks up to $s2 times."] = "$d 동안 받는 물리 피해 $s1만큼 증가최대 $s2번 중복",
    ["A massive uppercut that Inflicts $s1 Physical damage.\nKnocks the enemy up."] =
    "거대한 주먹으로 올려쳐 $s1의 물리 피해를 입히고 멀리 밀쳐냅니다.",
    ["Linked with a nearby construct.\nDamage increased by $s1%."] = "주위 피조물과 연결됨공격력 $s1%만큼 증가",
    ["Misery awaits you..."] = "불행이 기다립니다...",
    ["Ice try, but you can't escape the Lord of Frost's grasp."] = "얼음처럼 차갑지만 서리 군주의 손아귀에서 벗어날 수 없습니다.",
    ["Inflicts $s1 Frost damage and knocks the enemy in the air."] = "$s1의 냉기 피해공중으로 날려 보냄",
    ["You are filled with rage."] = "분노함.",
    ["Damage and healing done reduced by $s1."] = "공격력 및 받는 치유 효과 $s1만큼 감소",
    ["Surrounded by dark memories."] = "어두운 기억에 휩싸입니다.",
    ["Immune to all harm."] = "모든 피해에 면역",
    ["Being awoken prematurely to dire effect."] = "광포 효과 전에 깨어남",
    ["The Pink Elekks are on parade!"] = "축제에 나선 분홍색 엘레크",
    ["Flailing Madly.\nChance to hit reduced by $s1%."] = "광기에 차 무기를 휘두릅니다. 적중률이 $s1%만큼 감소합니다.",
    ["Inflicts $s1% of normal weapon damage."] = "무기 공격력의 $s1 피해",
