    ["Invoke the power of Freya atop the Glimmering Pillar."] = "미명의 봉우리 꼭대기에서 프레이야의 힘을 기원합니다.",
    ["Caught in a flimsy net. Act quickly - it doesn't look like it will hold long."] = "허술한 그물에 걸림그물이 허술하니 빨리 움직이십시오.",
