    ["Warning, you've entered an area where there is a magical no-fly zone in effect."] = "경고! 이 지역은 마법으로 비행이 통제되고 있습니다.",
    ["Afflicted with corrupted ley energy, causing $s1 Arcane damage every $t seconds."] =
    "타락한 지맥의 힘으로 매 $t초마다 $s1의 비전 피해",
