    ["Banishing Scourge crystal."] = "스컬지 수정 파괴",
    ["$s1 damage every $t$s2 seconds.\nMagic damage taken increased by $s3%."] = "매 $t$s2초마다 $s1의 피해받는 마법 피해 $s3만큼 증가",
    ["Teleported recently. \nCannot teleport again for a short time.\nYour body feels lighter."] =
    "최근 순간이동일정 시간 동안 순간이동 불가몸이 가벼워진 것 같습니다.",
    ["Your recent return from the dead has granted you temporary protection."] = "무덤 부활 후 일시적인 보호 상태가 되었습니다.",
    ["Warning, you've entered an area where the air is too thin for normal flight."] = "경고! 공기 밀도가 약해 일반적인 비행이 불가능합니다.",
    ["Increases Fire damage by $s1%.\nReduces damage taken by $s2%."] = "화염 공격력 $s1%만큼 증가받는 피해 $s2%만큼 감소",
    ["Everyone sees just how awesome you are, because you're Just. That. Amazing."] = "모든 이들의 주목을 받고 있습니다. 정말 대단해요!",
    ["Increases Fire and Shadow damage taken by $s1%.\nShadow damage taken upon attacking."] =
    "받는 화염 및 암흑 피해 $s1%만큼 증가공격 시 암흑 피해 받음",
    ["Maximum health reduced by $s1%.\n$s2 Shadow damage inflicted every $t$s3 sec."] =
    "최대 생명력 $s1%만큼 감소매 $t$s3초마다 $s2의 암흑 피해",
    ["Removes all movement impairing effects and increases the movement speed of you and your Spirit Wolves."] =
    "모든 이동 방해 효과를 제거하고 주술사와 늑대 정령의 이동 속도를 증가시킵니다.",
    ["Converts $$s1s$s2% damage to health."] = "$$s1s$s2%의 피해를 생명력으로 전환",
    ["Unable to cast or attack."] = "공격 및 시전 불가",
    ["Increases damage done by pet special abilities by $$s1s$s2%."] = "야수의 특수 능력으로 입히는 피해가 $$s1s$s2%만큼 증가합니다.",
    ["Infused with the spirit of Midsummer."] = "한여름 축제의 정신으로 충만합니다.",
    ["Suffering $s1 Nature damage per second.\nHit chance decreased by $s2%."] = "매초마다 $s1의 자연 피해적중률 $s2%만큼 감소",
    ["Shadowmelded."] = "그림자 속으로 사라짐",
    ["Spirit increased by $s1% and allows $s2% mana regeneration while casting."] = "정신력 $s1%만큼 증가시전 중 $s2%의 마나 회복",
    ["Adds an additional $s1 armor penetration rating."] = "방어구 관통력 $s1만큼 증가",
    ["Your next Howling Blast will consume no runes."] = "다음 작렬하는 분노는 룬을 소비하지 않음",
    ["Welded to the ground.\nNature damage inflicted while moving."] = "땅에 용접당함. 이동 중 자연 피해",
