    ["Riding shotgun."] = "길동무 중",
    ["Stunned and immobilized."] = "기절함. 이동 불가",
    ["Increased chance to fish up coins in the Dalaran fountain."] = "달라란 분수에서 낚시를 성공할 확률 증가",
    ["$s1% damage healed every $t$s2 sec."] = "매 $t$s2초마다 $s1%의 생명력 회복",
    ["You are bombing stuff."] = "당신은 튕겨 나왔습니다.",
    ["Increases stats by $s1."] = "모든 능력치 $s1만큼 증가",
    ["Dodge rating increased by $s1."] = "회피 숙련도 $s1만큼 증가",
    ["Inflicting $s1 damage every $t$s2 sec. to nearby enemies"] = "주위 적에게 매 $t$s2초마다 $s1의 피해를 입힙니다.",
    ["You are covered in eel oil!  On the bright side, at least your dodge rating has increased by $s1."] =
    "온통 뱀장어 기름투성이입니다. 회피 숙련도가 $s1만큼 증가합니다.",
    ["Burning."] = "불태움",
    ["Inflicts $s1 Shadow damage to an enemy every $$s2t$s3 sec."] = "매 $$s2t$s3초마다 $s1의 암흑 피해",
    ["Protects the bomber.  The more shield charges that remain, the more damage absorbed."] =
    "폭격기를 보호합니다.유효 횟수가 많이 남아 있을 수록 더 많은 피해를 흡수합니다.",
    ["Expertise rating increased by $s1."] = "숙련도 $s1만큼 증가",
    ["$s1 Mana burned every $t$s2 sec."] = "매 $t$s2초마다 $s1의 마나 연소",
    ["$h% chance of enveloping attackers in Shadows on hit."] = "공격 당하면 $h%의 확률로 공격자에게 피해",
    ["Nature damage taken increased by $s1%.\nDamage taken is increased the greater the distance from Loken."] =
    "받는 자연 피해 $s1%만큼 증가로켄에게서 멀리 떨어질수록 피해 증가",
    ["Suffering $s1 Shadow damage every $t$s2 sec."] = "매 $t$s2초마다 $s1의 암흑 피해",
    ["Increases damage done by $s1%"] = "공격력 $s1%만큼 증가",
    ["Increases damage done by $s1%.\nIncreases maximum health by $s2."] = "공격력 $s1%만큼 증가최대 생명력 $s2만큼 증가",
    ["Drawing the attention of all Forsaken foes."] = "모든 포세이큰 도발",
    ["Stunned.\n$s1 Shadow damage inflicted every $t$s2 sec.\nHealing taken reduced by $s3%.\nDamage to Prince Taldaram may break this effect."] =
    "기절함. 매 $t$s2초마다 $s1의 암흑 피해받는 치유 효과 $s3%만큼 감소공작 탈다람에게 피해를 입히면 효과가 사라질 수 있음",
    ["Physical damage dealt is increased by $s1%.\nAttack speed increased by $s2%.\nCasting speed increased by $s2%."] =
    "물리 공격력 $s1%만큼 증가공격 속도 $s2%만큼 증가시전 속도 $s2%만큼 증가",
    ["You are waiting for your bomber to arrive."] = "폭격기 도착을 기다리는 중입니다.",
    ["Causes the abomination to explode, killing Scourge units at the base of Mord'rethar."] =
    "누더기골렘을 폭발시켜 모드레타르 기지에 있는 스컬지를 처치",
    ["Your next Flash of Light or Exorcism spell is instant cast."] = "다음 빛의 섬광 혹은 퇴마술은 즉시 시전됨",
    ["Jump your jumpbot to the top of the mountain in Ymirheim and plant the Alliance Battle Standard.\n\nCan only be controlled within Ymirheim."] =
    "이미르하임에 있는 산꼭대기에서 도약로봇을 뛰어오르게 하여 얼라이언스 전투 깃발 꽂기이미르하임 안에서만 조종할 수 있음",
    ["Attack power increased by $s1 but armor reduced by $s2%."] = "전투력 $s1만큼 증가방어도 $s2%만큼 감소",
    ["All threat transferred from rogue to target."] = "모든 위협 수준 대상에게 이전",
    ["Inflicts $$s1s$s2 nature damage to all those caught in its destructive path."] =
    "앞을 가로막는 모든 적에게 $$s1s$s2의 자연 피해를 입힙니다.",
    ["You sure about this?  This elixir only works in the City of Dalaran."] = "정말 마시겠습니까? 이 비약은 달라란에서만 효과가 있습니다.",
    ["Be bathed in the power of the Warchief! Drink in his might! Battle for the glory of the Horde!"] =
    "대족장의 힘이 물결친다! 몸을 적시고 그 힘을 마셔라! 호드의 영광을 위하여 싸워라!",
    ["You have been transformed into a Hungry Tuskarr.  Fishing skill increased by $s1."] =
    "배고픈 투스카르가 되었습니다.낚시 숙련도가 $s1만큼 증가합니다.",
    ["You can see in the infra-green spectrum."] = "녹외선 분광 안에서 볼 수 있습니다.",
    ["Jump your jumpbot to the top of the mountain in Ymirheim and plant the Horde Battle Standard.\n\nCan only be controlled within Ymirheim."] =
    "이미르하임에 있는 산꼭대기에서 도약로봇을 뛰어오르게 하여 호드 전투 깃발 꽂기이미르하임 안에서만 조종할 수 있음",
    ["Damage dealt increased by $s1%.\nDamage taken reduced by $s2%."] = "공격력 $s1%만큼 증가받는 피해 $s2%만큼 감소",
    ["Return to Ymirheim immediately.\n\nFailure to do so will result in your jumpbot falling apart!"] =
    "이미르하임으로 돌아가지 않으면 추진기가 고장날 것입니다!",
    ["Corrupting the whelp within."] = "알 안에 있는 새끼용을 타락시킵니다.",
    ["When damaged, reduces healing recieved by the attacker by $$s1s$s2%."] = "피해를 받으면 공격자가 받는 치유 효과 $$s1s$s2%만큼 감소",
    ["Decreases healing recieved by $s1%."] = "받는 치유 효과 $s1%만큼 감소",
    ["Increases damage by $s1% and movement speed by $s2%. Lasts $s3 mins."] = "공격력 $s1%만큼 증가이동 속도 $s2%만큼 증가$s3분 동안 지속",
    ["Battle prowess heightened by the song of Sylvanas."] = "실바나스의 노래로 전투의 사기가 고조됩니다.",
    ["Grants a chance to deal poison damage and Increases movement speed by $s1%. Lasts $s2 mins. Can only be used in Sholazar Basin."] =
    "일정 확률로 독 피해이동 속도 $s1%만큼 증가$s2분 동안 지속",
    ["Restores Mana, Rage, Energy, or Runic Power when you kill a target that grants honor or experience."] =
    "대상을 처치하고 명예 점수나 경험치를 받으면 마나, 기력, 분노, 룬 마력 회복",
    ["Mana, Energy, Rage, or Runic Power Restored."] = "마나, 기력, 분노, 룬 마력이 회복됩니다.",
    ["Unable to act, but immune to damage."] = "움직일 수 없습니다.피해에 면역",
    ["Your critical strike rating is increased by $s1."] = "치명타 및 주문 극대화 적중도 $s1만큼 증가",
    ["You have been transformed into flying wasp.This effect only applies in the city of Dalaran."] =
    "말벌이 되었습니다.달라란에서만 효과가 있습니다.",
    ["Cannot be affected by Abomination Hook."] = "누더기골렘 고리에 영향을 받지 않음",
    ["The winds carry you to safety."] = "바람을 타고 안전하게 내려갑니다.",
    ["You had always heard that this was \"The City of Mages\" but this is ridiculous!"] =
    "\"마법사들의 도시\"라는 말은 항상 들었지만 이건 정말 신기합니다!",
    ["Grants you $s1 honor."] = "명예 점수가 $s1만큼 증가",
    ["Prevented from firing."] = "발사를 막음",
    ["$s1% spell haste until next spell cast."] = "다음 주문 시전 시 가속 $s1%만큼 증가",
    ["Carried to safety by the spirits of air."] = "바람의 정령이 안전하게 내려줍니다.",
    ["Charges remaining."] = "남은 사용 횟수",
    ["Health increased by $s1%"] = "생명력 $s1%만큼 증가",
    ["Increases the damage done by $s1%  and the attack speed by $s2% for all Scourge within $a$s3 yards."] =
    "주위 $a$s3미터 반경에 있는 스컬지의 공격력은 $s1%만큼, 공격 속도는 $s2%만큼 증가",
    ["Death comes swiftly."] = "죽음은 갑자기 찾아옵니다.",
    ["Reduces all damage by and you regenerate $s1% mana every $t$s2 sec for $d.  Cannot attack or cast spells."] =
    "$d 동안 받는 모든 피해 감소 및 매 $t$s2초마다 $s1%의 마나 회복공격 및 주문 시전 불가",
    ["fdas"] = "돌풍",
    ["Smelling great!"] = "냄새 좋군요!",
    ["$s1 Shadow damage inflicted every $t$s2 sec.\nAttack and casting speeds reduced by $s3%."] =
    "매 $t$s2초마다 $s1의 암흑 피해공격 및 시전 속도 $s3%만큼 감소",
    ["Babyized."] = "아기로 변신",
    ["Arcane damage inflicted over $d."] = "$d에 걸쳐 비전 피해",
    ["Dealing $s1% more damage."] = "공격력 $s1%만큼 증가",
    ["Caught in the grip of the Lich King."] = "리치 왕의 손아귀에 걸렸습니다.",
    ["They come..."] = "그들이 온다...",
    ["Increases your armor penetration rating by $s1."] = "방어구 관통력 $s1만큼 증가",
    ["Increases an ally's attack speed and damage done by $s1%."] = "아군의 공격 속도 및 공격력 $s1%만큼 증가",
    ["Allows the gathering of Tainted Essence from dead cultists in Aldur'thar."] = "알두르타르에 있는 죽은 이교도에게서 부정한 정기를 수집",
    ["Increases Hit Rating by $s1."] = "적중도 $s1만큼 증가",
    ["Increases Critical Rating by $s1."] = "치명타 및 주문 극대화 적중도 $s1만큼 증가",
    ["Increases Defense Rating by $s1."] = "방어 숙련도 $s1만큼 증가",
    ["Increases Armor Penetration Rating by $s1."] = "방어구 관통력 $s1만큼 증가",
    ["Increases Haste Rating by $s1."] = "가속도 $s1만큼 증가",
    ["Increases maximum health by $s1%.\nIncreases damage done by $s2%."] = "최대 생명력 $s1%만큼 증가공격력 $s2%만큼 증가",
    ["Increases spell damage taken by $s1%."] = "받는 마법 피해 $s1%만큼 증가",
    ["You were too high a level to use your scroll of recall and it teleported you randomly."] =
    "귀환의 두루마리를 사용했지만 레벨이 너무 높아 무작위 장소로 순간이동되었습니다.",
    ["Periodic shadow damage taken increased by $s1%, and periodic healing recieved reduced by $s2%."] =
    "주기적인 암흑 피해 $s1%만큼 증가주기적인 치유 효과 $s2%만큼 감소",
    ["Shadow damage dealt is increased by $s1%."] = "암흑 공격력 $s1%만큼 증가",
    ["Infused with corrupted temporal energy."] = "부패한 시간의 힘 주입됨",
    ["Allows the use of Overpower."] = "제압 사용 가능",
    ["For the Alliance!"] = "얼라이언스를 위하여!",
    ["For the next $d, your direct heals increase healing received by their target by up to $$s1s$s2.  This effect lasts $$s1d and stacks up to $s3 times."] =
    "다음 $d 동안 대상에 대한 자신의 직접 치유 주문의 치유 효과가 최대 $$s1s$s2만큼 증가합니다. $$s1d 동안 지속되며 최대 $s3번까지 중복됩니다.",
    ["Your vehicle is on fire!"] = "차량에 불이 붙었습니다!",
    ["Get over here!"] = "이리 오너라!",
    ["Your Shock spells grant $$s1s$s2 spell power for $$s1d."] = "충격 계열 주문 사용 시 $$s1d 동안 주문력 $$s1s$s2만큼 증가",
    ["$s1% of maximum health dealt in damage every $t$s2 sec."] = "매 $t$s2초마다 대상의 최대 생명력의 $s1%의 피해",
    ["Healing reduced by $s1%.\nPhysical damage taken increased by $s2."] = "치유 효과 $s1%만큼 감소받는 물리 피해 $s2만큼 증가",
    ["Physical damage increased by $s1%.\nAttack Speed increased by $s2%."] = "물리 공격력 $s1%만큼 증가공격 속도 $s2%만큼 증가",
    ["Suffering $s1 damage every $t$s2 sec."] = "매 $t$s2초마다 $s1의 피해",
    ["Carried by the winds to Orgrimmar."] = "바람에 실려 오그리마로 돌아갑니다.",
    ["Your violent tendencies are soothed by the presence of the Dragon Queen."] = "용의 여왕이 나타나자 난폭한 기운이 사그라듭니다.",
    ["Immune to all Curse effects."] = "모든 저주 효과에 면역",
    ["Being targetted by a turret."] = "포탑에 공격받음",
    ["Attack and cast speed reduced by $s1%."] = "공격 속도 및 시전 속도 $s1%만큼 감소",
    ["Increases Physical damage taken by $s1%"] = "받는 물리 피해 $s1%만큼 증가",
    ["Whirls around, dealing damage to nearby enemies."] = "소용돌이로 적을 공격하여 주위 적에게 피해를 입힙니다.",
    ["Inflicts $s1 Arcane damage to enemies in front of the caster."] = "시전자 전방의 적에게 $s1의 비전 피해를 입힙니다.",
    ["You recently finished a sortie."] = "최근에 폭격을 마치고 돌아왔습니다.",
    ["Battle prowess heightened by Jaina's powerful spell."] = "제이나의 강력한 주문으로 전장의 사기가 고조됩니다.",
    ["Runeblade empowered with Shadow energy."] = "어둠의 힘으로 룬검 강화",
    ["Grants $s1 Runic Power."] = "$s1의 룬 마력 회복",
    ["You are witnessing the raising of Sindragosa and cannot move."] = "신드라고사가 일어나는 모습을 지켜보는 동안은 움직일 수 없습니다.",
    ["Melee attack power reduced by $s1%."] = "근접 전투력 $s1%만큼 감소",
    ["Your Spirit is increased by $s1."] = "정신력 $s1만큼 증가",
    ["Summoning Zombies.\nDamage reduced by $s1%."] = "좀비 소환받는 피해 $s1%만큼 감소",
    ["Extinguish a fire on your bomber, if it is burning."] = "폭격기에 붙은 불 끄기",
    ["Your heart has been grazed by Illidan's glaives.  If only you could rid yourself of this useless thing..."] =
    "일리단이 던진 글레이브가 당신의 심장을 스치고 지나갔습니다. 그 쓸모없는 것을 떼어낼 수만 있다면...",
    ["Being eaten alive!"] = "산 채로 먹히고 있습니다!",
    ["Kills reported during this sortie."] = "이번 출격에서 적을 처치한 횟수 보고",
    ["Disguised as a member of the Cult of the Damned.  Looks out of place outside the Cathedral of Darkness."] =
    "저주받은 자들의 교단 일원으로 변장 어둠의 대성당 밖에서는 어울리지 않음",
    ["Knocked down."] = "넘어짐",
