    ["All that turkey has made you tired."] = "칠면조 요리를 잔뜩 먹어서 졸음이 밀려옵니다.",
    ["Shhh! Did you hear that? Don't move!"] = "쉿! 소리가 들리나요? 움직이지 마세요!",
    ["You are a sheep.  Cannot cast spells while in sheep form.  Right-Click this icon to remove the effect."] =
