    ["Inflicts $s1 Nature damage every $t$s2 sec.\nCauses Brittle Skin."] = "매 $t$s2초마다 $s1의 자연 피해부서지는 피부 유발",
    ["Your knuckles are cracked and ready for action!"] = "손마디 꺾기 및 준비 완료",
    ["Your muscles are stretched out and ready for action!"] = "기지개 펴기 및 준비 완료",
    ["$s1 Frost damage every $s2 sec.\nMovement diminishes this effect."] = "매 $s2초마다 $s1의 냉기 피해이동 시 효과 감소",
    ["Stunned.\n$s1 Physical damage inflicted every $t$s2 sec.\nDamage to Kologarn may break this effect."] =
    "기절함. 매 $t$s2초마다 $s1의 물리 피해콜로간에게 피해를 입히면 효과가 사라질 수 있음",
    ["Your mount will be more festive."] = "축제 분위기에 맞게 탈것을 바꿉니다.",
    ["You're riding a player. Good times."] = "플레이어를 태우고 있습니다.재미있는 시간 되세요.",
    ["Damage increased by $s1%.\n\n|cFFFFAA$s2\"The southern towers draw power from the fortress. Once destroyed, the power is restored.\" - Mekgineer Sprocketwrench|r"] =
    "공격력 $s1%만큼 증가|cFFFFAA$s2\"남쪽 지역의 탑들이 요새의 힘을 끌어오고 있습니다. 탑이 파괴되면 요새로 힘이 복원됩니다.\" - 기계박사 스프로켓렌치|r",
    ["Now all can see how strong you are!"] = "모두에게 힘자랑",
    ["Shoes are shiny."] = "신발이 반짝거립니다.",
    ["Teleport player to inside Violet Hold."] = "플레이어를 보랏빛 요새로 순간이동시킵니다.",
    ["Your Defense rating is increased by $s1."] = "방어 숙련도 $s1만큼 증가",
    ["Stunned.\n$s1 Physical damage inflicted every $t$s2 sec.\nDamage to Kologarn's Arm may break this effect."] =
    "기절함. 매 $t$s2초마다 $s1의 물리 피해콜로간의 팔에 피해를 입히면 효과 해제 가능",
    ["Your latest attempt at the cannon was dead on!"] = "대포 발사로 정확히 명중",
    ["Your latest attempt at the cannon was close to the center, but not close enough."] = "대포 발사로 목표에 근접했으나 명중 실패",
    ["Your latest attempt at the cannon landed you near the target area.  Better luck next time!"] =
    "잘못 발사하여 목표 지역 근처로 튕김다음 기회에!",
    ["Hidden Dummy Aura when wearing a White Tuxedo Shirt and Black Tuxedo Pants, the Spring Tuxedo set."] =
    "흰색 턱시도 셔츠, 검은색 턱시도 바지, 새봄맞이 턱시도 세트의 숨은 허수아비 오라",
    ["Increases damage dealt by $s1% until the energy of the beam collapses."] = "광선의 에너지가 붕괴할 때까지 공격력 $s1%만큼 증가",
    ["The rays of the sun heals the plant life for $s1 damage every $t$s2 sec."] =
    "태양 광선이 식물을 치료하여 매 $t$s2초마다 $s1의 생명력 회복",
    ["Being energized by the power of the Sun."] = "태양의 힘으로 충만",
    ["Inflicts $s1 Nature damage and cancels the effects of Unstable Sun Beam."] = "$s1의 자연 피해불안정한 태양 광선의 효과 취소",
    ["Frenzy is unleashed when the Ghoul thrashes."] = "구울이 난타 공격 시 광기를 방출합니다.",
    ["Inflicts $s1 Fire damage to a number of targets based on Brightleaf Flux."] =
    "밝은잎의 에너지 흐름을 기준으로 다수 대상에게 $s1의 화염 피해",
    ["You are paralyzed. Watch your step!  You hear the sharp clang of metal and cries of agony from the arena beyond, where your companions are fighting a pitched battle. What do you suppose they would say if they could see you now?"] =
    "마비 상태가 되었습니다. 조심하십시오! 투기장 저편에서 날카로운 쇳소리와 고뇌의 울음소리가 들려옵니다. 그곳에서 당신의 동료가 어려운 전투를 벌이고 있습니다. 그들이 당신을 본다면 어떤 말을 할까요?",
    ["Increases damage and healing done by $s1%.\nUnstable Explosion will cancel the effects of Unstable Sun Beam."] =
    "공격력과 치유량 $s1%만큼 증가불안정한 폭발로 효과 취소",
