    ["Deals $s1 Shadow damage every half-second."] = "매 0.5초마다 $s1의 암흑 피해",
    ["Absorbs $s1 damage.\nIncreases damage done by $$s2s$s3% when broken by damage."] =
    "$s1의 피해 흡수피해를 입어 파괴되면 공격력 $$s2s$s3% 증가",
    ["Melee damage and attack speed increased by $s1%.\nNature damage increased by $s2%."] =
    "근접 공격력 및 공격 속도 $s1%만큼 증가자연 공격력 $s2%만큼 증가",
    ["Inflicts $s1 Nature damage to enemies within $a$s2 yards of the target."] =
    "대상으로부터 $a$s2미터 반경 내에 있는 적들에게 $s1의 자연 피해",
    ["The flaming tar burns anything nearby."] = "뜨거운 타르가 주위의 모든 것을 태워버립니다.",
    ["Frozen.\nCan be broken by flames."] = "얼어붙음불에 의해 깨질 수 있음",
    ["Damage and health increased with gear level."] = "장비 수준에 따라 생명력과 공격력 증가",
    ["Inflicts $s1 Physical damage every $t$s2 sec.\nStunned."] = "매 $t$s2초마다 $s1의 물리 피해기절함.",
    ["Suffering $s1 damage per $t$s2 sec."] = "매 $t$s2초마다 $s1의 피해",
    ["Melee, ranged, and casting speed increased by $s1%."] = "근접 및 원거리 공격 속도, 주문 시전 속도 $s1%만큼 증가",
    ["Absorbing up to $s1 magical damage.\nPhysical damage taken reduced by $s2%."] =
