    ["Champion of the Exodar."] = "엑소다르의 용사",
    ["You feel warm and fuzzy."] = "따뜻하고 몽롱합니다.",
    ["Reduces movement by $s1%."] = "이동 속도 $s1%만큼 감소",
    ["Valiant of the Argent Crusade."] = "은빛십자군의 용맹전사",
    ["Champion of the Argent Crusade."] = "은빛십자군의 용사",
    ["Increases damage dealt by $s1%.\nMelee attacks will release waves of electrical energy."] =
    "공격력 $s1%만큼 증가근접 공격 시 전하 에너지의 파동 방출",
    ["Immune to snare effects."] = "감속 효과에 면역",
    ["Damage dealt increased by $s1% while separated from a companion."] = "동료로부터 분리되어 있는 동안 공격력 $s1%만큼 증가",
    ["You are paralyzed. Watch your step! Thorim looms at the end of the corridor, almost close enough to touch. Assuming you weren't paralyzed, of course. But you are.  What a shame."] =
    "마비 상태가 되었습니다. 조심하십시오! 복도의 끝에 토림이 잡힐 듯 나타납니다. 물론 마비 상태가 아니라면 말이죠. 하지만 마비 상태이니 도리가 없군요. 부끄럽습니다.",
    ["Decreases the time between attacks by $s1% and heals $s2% every $t$s3 sec."] =
    "공격 간격 $s1%만큼 줄어듦매 $t$s3초마다 $s2%의 생명력 회복",
    ["Slows attack and cast speed by $$s1s$s2%.\nInflicts $s3 Frost damage every $t$s4 sec."] =
    "공격 및 시전 속도 $$s1s$s2%만큼 감소매 $t$s4초마다 $s3의 냉기 피해",
    ["Shocked."] = "충격에 휩싸임",
    ["Aspirant of the Argent Crusade."] = "은빛십자군의 지원자",
    ["Aspirant of the Knights of the Ebon Blade."] = "칠흑의 기사단 지원자",
    ["Valiant of the Knights of the Ebon Blade."] = "칠흑의 기사단 용맹전사",
    ["Champion of the Knights of the Ebon Blade."] = "칠흑의 기사단 용사",
    ["Learn a Second Talent Specialization."] = "2특성 익히기",
    ["Damage dealt increased by $s1%.\nAttack speed increased by $s2%."] = "공격력 $s1%만큼 증가공격 속도 $s2%만큼 증가",
    ["Summons Rubble."] = "잡석을 소환합니다.",
    ["Switch to your Secondary Talent Specialization."] = "2특성으로 전환",
    ["Switch to your Primary Talent Specialization."] = "1특성으로 전환",
    ["Revert to One Talent Specialization."] = "1특성으로 되돌립니다.",
    ["Teaches you how to switch between talent specs."] = "특성을 전환하는 방법을 배웁니다.",
    ["You have mechanic abilities!"] = "기계장치의 능력을 사용할 수 있습니다!",
    ["Pulsing negative energy every $t$s1 sec., burning the mana of nearby enemies."] =
    "매 $t$s1초마다 음에너지의 파동 방출주위 적의 마나 소진",
    ["Shielded by an impenetrable void barrier.  \nImmune to all damage."] = "꿰뚫을 수 없는 공허의 방벽으로 보호됨모든 피해에 면역",
    ["Critical strike damage increased by $s1%."] = "치명타 피해 $s1%만큼 증가",
    ["Cannot attack."] = "공격할 수 없습니다.",
    ["Hit rating increased by $s1.  Battle Elixir."] = "적중도 $s1만큼 증가전투 비약",
    ["Reduces the cast time of your next Greater Heal or Prayer of Healing by $s1%."] =
    "다음 상급 치유 혹은 치유의 기원 주문의 시전 시간 $s1%만큼 감소",
    ["Beams of light!"] = "광선 발사!",
    ["Transformed into an unstoppable dervish of whirling steel."] = "막을 수 없는 강철 소용돌이로 변신",
    ["$$s1s$s2 Shadow damage inflicted and $s3% Sanity lost every $t$s2 sec while linked player is more than $s4 yds away."] =
    "연결된 플레이어와 $s4미터 이상 떨어지면 매 $t$s2초마다 $$s1s$s2의 암흑 피해 및 $s3%의 이성 상실",
    ["Horrified.  This effect will attempt to jump to a nearby friend when removed."] =
    "극심한 공포에 휩싸임효과가 제거되면 주위 아군에게 옮겨질 수 있음",
    ["The heart of the XT-$s1 is exposed.\nDamage taken increased by $s2%."] = "XT-$s1의 심장 노출받는 피해 $s2%만큼 증가",
    ["Impervious to attacks and spells."] = "공격과 주문에 의한 피해 방지",
    ["Unkillable."] = "죽지 않음",
    ["Tractor Beam!"] = "유인 광선!",
    ["A guardian has teleported you out of the Silver Covenant Pavilion."] = "수호자가 당신을 은빛 서약단 막사에서 순간이동시켰습니다.",
    ["A guardian has teleported you out of the Sunreaver Pavilion."] = "수호자가 당신을 선리버 막사에서 순간이동시켰습니다.",
    ["Movement speed increased by $s1%.\n\n|cFFFFAA$s2\"Things are not what they seem.\"|r"] =
    "이동 속도 $s1%만큼 증가|cFFFFAA$s2\"보이는 걸 믿으면 안 됩니다.\"|r",
    ["Something about this creature seems... wrong."] = "이 생물은 뭔가가... 잘못된 것 같습니다.",
    ["Something about this object seems... wrong."] = "이 물건은 뭔가가... 잘못된 것 같습니다.",
    ["An Angry Oak Spirit appears to avenge the slain Crystalsong Oak!"] = "죽은 수정노래 떡갈나무의 복수를 위해 화난 떡갈나무 영혼이 나타납니다!",
    ["Attack power increased by $s1 and spell power increased by $s2."] = "전투력 $s1만큼 증가주문력 $s2만큼 증가",
    ["All damage dealt is increased by $$s1s$s2%.\nAttack and Movement speeds increased by $$s1s$s3%.\nImmune to Taunt."] =
    "모든 공격력 $$s1s$s2%만큼 증가공격 및 시전 속도 $$s1s$s3%만큼 증가도발에 면역",
    ["$s1 Shadow damage inflicted to enemies."] = "적에게 $s1의 암흑 피해",
    ["All damage done reduced by $s1%."] = "모든 공격력 $s1%만큼 감소",
    ["$s1 Nature damage inflicted every $t$s2 sec.\n$s3 Mana drained every $t$s2 sec."] =
    "매 $t$s2초마다 $s1의 자연 피해매 $t$s2초마다 $s3의 마나 흡수",
    ["Periodically retching uncontrollably."] = "주기적으로 제어할 수 없는 구토 유발",
    ["Attack and casting speeds reduced by $s1%.\nMovement speed reduced by $s2%."] =
    "공격 및 시전 속도 $s1%만큼 감소이동 속도 $s2%만큼 감소",
    ["$s1 Shadow damage inflicted after $d."] = "$d 후 $s1의 암흑 피해",
    ["Vulnerable to Titanic Storm."] = "티탄의 폭풍에 약점",
    ["Inflicting $$s1s$s2 Shadow damage and reducing the Sanity of all enemies facing the caster by $s3% every $t$s2 sec."] =
    "$$s1s$s2의 암흑 피해매 $t$s2초마다 시전자를 향하고 있는 적의 이성 $s3%만큼 감소",
    ["$s1% Sanity regenerated every $$s2t$s3 sec.\nDamage done reduced by $s4%."] =
    "매 $$s2t$s3초마다 $s1%의 이성 회복공격력 $s4%만큼 감소",
    ["Channeling a storm of titan energy that periodically strikes at enemy targets with bolts of lightning strong enough to destroy weakened immortal creatures."] =
    "티탄 에너지의 폭풍을 집중시켜 약해진 불멸의 생명체를 파괴시킬 수 있는 강력한 번개 화살을 주기적으로 적 대상에게 날려보내게 합니다.",
    ["Hodir will save you if you sustain damage that would otherwise kill you."] = "죽음에 이를 수 있는 피해로부터 호디르가 구해줍니다.",
    ["The fragments of Val'anyr are now inside Yogg-Saron's physical body."] = "발아니르 조각이 요그사론의 육체로 들어감",
    ["Deals $s1 Nature damage to attackers.\nImmune to stuns."] = "공격자에게 $s1의 자연 피해기절에 면역",
    ["Attacks made against the Lasher trigger the protective bark to grow, increasing damage done."] =
    "덩굴손이 공격을 받을 때마다 단단한 껍질이 자라나 공격력이 증가합니다.",
    ["Increases damage done by $s1%.\nIncreases total health by $s2%. \n\n|cFFFFAA$s3\"The heart no longer limits the XT-$s4 Deconstructor's combat capabilities.\"|r"] =
    "공격력 $s1%만큼 증가전체 생명력 $s2%만큼 증가|cFFFFAA$s3\"심장에서 XT-$s4의 전투 능력을 더 이상 제한하지 않습니다.\"|r",
    ["$s1% of all damage taken by party members redirected to the Paladin."] = "파티원이 받는 모든 피해의 $s1%가 자신에게 이전됨",
    ["$s1 Nature damage dealt every $t$s2 sec."] = "매 $t$s2초마다 $s1의 자연 피해",
    ["Next Fire Blast stuns the target for $$s1d."] = "다음 화염 작렬은 $$s1d 동안 대상을 기절시킵니다.",
    ["Restores $s1 health per second.  Unable to move or act."] = "매초마다 $s1의 생명력 회복이동 불가",
    ["Cannot attack members of the opposing faction while under the banner of the Argent Tournament."] =
    "은빛십자군 마상시합 깃발 아래에서는 다른 진영의 일원을 공격할 수 없습니다.",
    ["Inflicts $s1 Physical damage every $t$s2 sec."] = "매 $t$s2초마다 $s1의 물리 피해",
    ["$s1 Arcane damage inflicted."] = "$s1의 비전 피해",
    ["Other nearby Sentries increase damage done.\nIncreases damage done by $s1%."] = "주위 다른 감시자들의 공격력 증가공격력 $s1%만큼 증가",
    ["A massive blast that inflicts $$s1s$s2 Shadow damage and increases Shadow damage taken by $$s1s$s3% for $$s1d."] =
    "거대한 폭발을 일으켜 $$s1s$s2의 암흑 피해를 입히고 $$s1d 동안 받는 암흑 피해를 $$s1s$s3%만큼 증가시킵니다.",
    ["Strikes at an enemy, inflicting $s1 Physical damage."] = "적을 강하게 내리쳐 $s1의 물리 피해를 입힙니다.",
    ["You have been targeted by the Guardian Swarm!"] = "무리 수호자의 표적이 되었습니다!",
    ["You are fading from this plane of existence..."] = "현재 차원에서 멀어지고 있습니다...",
    ["Damage done by your Steady Shot, Aimed Shot, Black Arrow and Explosive Shot increased by $s1%."] =
    "고정 사격, 조준 사격, 검은 화살, 폭발 사격의 공격력 $s1%만큼 증가",
    ["Parry rating increased by $s1.  Deals $$s2s$s3 damage the next time you successfully parry an attack."] =
    "무기 막기 확률 $s1만큼 증가다음 무기 막기 성공 시 $$s2s$s3의 피해",
    ["Summons a Feral Defender to aid Auriaya."] = "수호 야수를 소환하여 아우리아야를 돕게 합니다.",
    ["Casts Seeping Feral Essence for damage every second."] = "야생의 정수를 침투시켜 매초마다 피해를 입힙니다.",
    ["The Seeping Essence of the Feral Defender Inflicts $s1 Shadow damage every $$s2t$s3 sec."] =
    "수호 야수의 야생의 정수로 매 $$s2t$s3초마다 $s1의 암흑 피해를 입힙니다.",
    ["Targeted for Empowering Shadows."] = "암흑 강화의 대상이 됨",
    ["$s1 Health regenerated every $t$s2 sec."] = "매 $t$s2초마다 $s1의 생명력 회복",
    ["Stunned.\nInflicts Shadow damage every $t$s1 sec."] = "기절함. 매 $t$s1초마다 암흑 피해",
    ["Reduces chance to Crit to $s1%."] = "치명타 적중도가 $s1%로 감소합니다.",
    ["Health increased by $s1%.\nFire damage taken reduced by $s2%."] = "생명력 $s1%만큼 증가받는 화염 피해 $s2%만큼 감소",
    ["Inflicts $s1 Arcane damage to enemies."] = "적에게 $s1의 비전 피해",
    ["Fire damage equal to $o$s1% of total health inflicted over $d."] = "$d에 걸쳐 전체 생명력의 $o$s1%에 해당하는 화염 피해",
    ["Deals $s1 Spellfire damage per second."] = "매초마다 $s1의 비전불꽃 피해",
    ["Heals for $$s1s$s2 if you are taken below $s3% health."] = "생명력이 $s3% 아래로 내려가면 생명력 $$s1s$s2만큼 회복",
    ["Damage taken from area of effect attacks reduced by $s1%."] = "광역 공격으로 받는 피해 $s1%만큼 감소",
    ["Your insight into Judgements of the Wise is intensified but corrupted by General Vezax's Aura of Despair, hindering your ability to heal."] =
    "현자의 심판에 대한 통찰력이 강화되었으나 장군 베작스의 절망의 오라에 의해 타락하여 치유 능력을 사용할 수 없습니다.",
    ["Blinded."] = "볼 수 없음",
    ["$s1 Frost damage every $t$s2 sec."] = "매 $t$s2초마다 $s1의 냉기 피해",
    ["Restoring health."] = "생명력 회복 중",
    ["Immobilized.\nDamage taken increased by $s1%"] = "이동 불가받는 피해 $s1%만큼 증가",
    ["Absorbing physical. frost, arcane and fire damage."] = "물리, 냉기, 비전, 화염 피해 흡수",
    ["Kologarn squeezes the target of its remaining life, dealing $s1 Physical damage."] =
    "콜로간이 대상에게 남은 생명력을 쥐어짜내 $s1의 물리 피해를 입힙니다.",
    ["Consumed in unquenchable fire. Only the cooling waters of Ignis's forge will extinguish this flame."] =
    "억제할 수 없는 불길에 흡수됨이그니스의 용광로에 있는 냉각수로만 불길을 끌 수 있음",
    ["Kologarn squeezes the target of it's remaining life dealing $s1 Physical damage."] =
    "콜로간이 대상에게 남은 생명력을 쥐어짜내 $s1의 물리 피해를 입힙니다.",
    ["Dealing $$s1s$s2 Arcane damage per second."] = "매초마다 $$s1s$s2의 비전 피해",
    ["Firing a barrage of arcane attacks."] = "비전력 탄막 발사",
    ["This vehicle has taken major damage.\nIt will only last a few more minutes."] = "큰 피해를 받았습니다.몇 분밖에 버티지 못합니다.",
    ["Armor reduced by $s1%.\nAttack speed reduced by $s2%.\nMovement speed reduced by $s3%."] =
    "방어도 $s1%만큼 감소공격 속도 $s2%만큼 감소이동 속도 $s3%만큼 감소",
    ["Your armor has fused together rendering you unable to act!"] = "방어구가 겹겹이 녹아 움직일 수 없습니다!",
    ["Inflicts $s1 Arcane damage."] = "$s1의 비전 피해를 입힙니다.",
    ["Inflicts Arcane damage around the Device."] = "장치 주위에 비전 피해를 입힙니다.",
    ["Heals damage every $t$s1 seconds."] = "매 $t$s1초마다 생명력 회복",
    ["You have recently bested a rider of Darnassus and may not challenge one again."] =
    "최근 다르나서스 기수 한 명을 꺾었습니다. 다시 도전할 수 없습니다.",
    ["You have recently bested a rider of the Exodar and may not challenge one again."] =
    "최근 엑소다르 기수 한 명을 꺾었습니다. 다시 도전할 수 없습니다.",
    ["You have recently bested a rider of Gnomeregan and may not challenge one again."] =
    "최근 놈리건 기수 한 명을 꺾었습니다. 다시 도전할 수 없습니다.",
    ["You have recently bested a rider of Ironforge and may not challenge one again."] =
    "최근 아이언포지 기수 한 명을 꺾었습니다. 다시 도전할 수 없습니다.",
    ["You have recently bested a rider of Orgrimmar and may not challenge one again."] =
    "최근 오그리마 기수 한 명을 꺾었습니다. 다시 도전할 수 없습니다.",
    ["You have recently bested a rider of Sen'jin and may not challenge one again."] =
    "최근 센진 기수 한 명을 꺾었습니다. 다시 도전할 수 없습니다.",
    ["You have recently bested a rider of Silvermoon City and may not challenge one again."] =
    "최근 실버문 기수 한 명을 꺾었습니다. 다시 도전할 수 없습니다.",
    ["You have recently bested a rider of Stormwind and may not challenge one again."] =
    "최근 스톰윈드 기수 한 명을 꺾었습니다. 다시 도전할 수 없습니다.",
    ["You have recently bested a rider of Thunder Bluff and may not challenge one again."] =
    "최근 썬더 블러프 기수 한 명을 꺾었습니다. 다시 도전할 수 없습니다.",
    ["You have recently bested a rider of the Undercity and may not challenge one again."] =
