    ["Periodically inflicting Fire damage to enemeis within $$s1a$s2  yards."] = "주기적으로 $$s1a$s2미터 반경 내의 아군에게 화염 피해",
    ["Inflicts Fire damage."] = "화염 피해",
    ["Frozen. Brrrr...."] = "얼어붙음. 부르르...",
