    "주 대상과 그로부터 $s1미터 반경 내에 있는 주변 대상에게 피해를 동일하게 나누어 입힙니다.",
    ["Melee damage and attack speed increased by $s1%."] = "근접 공격력 및 공격 속도 $s1%만큼 증가",
