    ["The toxin has shut down your nervous system entirely, paralyzing you."] = "독으로 전체 신경계가 정지하여 마비됩니다.",
    ["Blinded by the light."] = "빛으로 눈이 멂",
    ["Melee attacks have a chance to cause the caster's next melee swing to be a critical strike."] =
