    "영혼의 지배자가 받는 피해의 일정 비율에 해당하는 피해를 비춰진 영혼에게 되돌립니다.",
    ["A percentage of damage from the Devourer of Souls is being mirrored with you."] =
    "영혼의 포식자가 받는 피해의 일정 비율에 해당하는 피해를 입습니다.",
