    ["Attacks have a chance to apply Unholy Frenzy."] = "공격 시 일정 확률로 부정의 광기 발동",
    ["Conjuring bone spikes."] = "뼈 가시 생성",
    ["Stunned.\nBleeding."] = "기절함. 출혈",
    ["Attacking all nearby enemies in a whirlwind of bone."] = "뼈의 소용돌이로 주위 모든 적 공격",
    ["Deals $s1 Shadow damage to an enemy target, decreasing their damage done by $$s2s$s3%."] =
