    "착용자를 공중으로 날아오르게 합니다. 착륙 시 적들에게 피해를 입히고 공격 및 이동 속도를 감소시킵니다. 비행시간이 길수록 효과가 큽니다.",
    ["Violently releases the Gaseous Blight, dealing $s1 Shadow damage to all enemy players, releasing the deadly Blight back into the room."] =
    "파멸의 역병 가스를 거칠게 내뿜어 모든 적 플레이어에게 $s1의 암흑 피해를 입히고 실내에 치명적인 파멸의 역병을 다시 퍼뜨립니다.",
    ["Movement speed reduced by $s1%.\nSuffering $s2 Frost damage per $t$s3 sec."] =
    "이동 속도 $s1%만큼 감소매 $t$s3초마다 $s2의 냉기 피해",
    ["Inflicts $s1 damage every $t$s2 sec.\nDisoriented."] = "매 $t$s2초마다 $s1의 피해방향 감각 상실",
    ["Marked for attack."] = "공격의 표적이 되었습니다.",
    ["You have the Gas Spore! You will explode and infect all nearby friendly players, dealing $$s1s$s2 Shadow damage and increasing their resistance to the Blight."] =
    "가스 포자에 감염되었습니다! 곧 폭발하여 주위 모든 플레이어를 감염시키고 $$s1s$s2의 암흑 피해를 입히며 파멸의 역병에 대한 저항력을 증가시킵니다.",
    ["Decreases Shadow damage taken by $s1%."] = "받는 암흑 피해 $s1%만큼 감소",
    ["Deals $$s1s$s2 Fire damage to all enemies every $t$s2 sec."] = "주위 모든 적에게 매 $t$s2초마다 $$s1s$s2의 화염 피해",
    ["Healing $s1 every second.\nDamage dealt increased proportional to health."] = "매초마다 $s1의 생명력 회복생명력에 비례하여 공격력 증가",
    ["Heals the caster for half of any damage dealt."] = "시전자는 입힌 피해의 반만큼 생명력 회복",
    ["Deals increasing Shadow damage per second."] = "매초마다 증가하는 암흑 피해",
    ["Deals $s1 Shadow damage and the caster gains $$s2s$s3% bonus physical damage after $d."] =
    "$d 후 $s1의 암흑 피해 및 시전자의 물리 공격력 $$s2s$s3%만큼 증가",
    ["You've sampled one of the Crown Chemical Company's many fine holiday products.  Disclaimer:  Satisfaction not guaranteed to last the full duration."] =
    "왕관화학회사에서 제공하는 고급 축제 상품의 견본을 사용했습니다. 주: 제품의 효과는 표기된 시간만큼 지속되지 않을 수 있습니다.",
    ["Siphons health from the target and nearby enemies after $d."] = "$d 후 대상과 주변의 적으로부터 생명력 흡수",
    ["The cannon has overheated!\nFire controls temporarily offline."] = "대포가 과열되었습니다!잠시 동안 발사할 수 없습니다.",
    ["$s1% damage every $t$s2 seconds."] = "매 $t$s2초마다 $s1%의 피해",
    ["Inflicts Nature damage periodically."] = "주기적인 자연 피해",
    ["Carrying saronite rocks."] = "사로나이트 바위 운반 중",
    ["Resilience rating and Stamina increased by $s1. Brewfest beers: Great taste, extra-filling!"] =
    "탄력도 및 체력 $s1만큼 증가가을 축제 맥주: 상쾌하고 풍부한 맛입니다!",
    ["Dealing Nature damage every $t$s1 sec.\nSpreads to a nearby target after $d."] = "매 $t$s1초마다 자연 피해$d 후 주위 대상에게 이동",
    ["Regenerating health.\nAll damage taken reduced by $s1%."] = "생명력 회복받는 모든 피해 $s1%만큼 감소",
    ["Armor increased by $s1%\nAttack speed increased by $s2%."] = "방어도 $s1%만큼 증가공격 속도 $s2%만큼 증가",
    ["Attack speed decreased by $s1%.\nMovement speed decreased by $s2%."] = "공격 속도 $s1%만큼 감소이동 속도 $s2%만큼 감소",
    ["Wearing an enchanted Sunreaver Tabard. This disguise will only work in Dalaran."] = "마법의 선리버 휘장 착용달라란에서만 효과 있음",
    ["Wearing an enchanted Silver Covenant Tabard. This disguise only works in Dalaran."] =
    "마법의 은빛 서약단 휘장 착용달라란에서만 효과 있음",
    ["Inflicts $s1 damage every $t$s2 sec.\nReduces healing received by $s3%.\nWhen the Infection is removed a Small Ooze is created."] =
    "매 $t$s2초마다 $s1의 피해받는 치유 효과 $s3%만큼 감소전염병 해제 시 작은 수액괴물 생성",
    ["Frozen in a block of ice. Unusable."] = "얼어붙음쓸모없음",
    ["Imprisoned in ice, unable to attack, move or use spells. Immune to all attacks and spells."] =
    "얼음에 갇힘공격 및 이동, 주문 시전 불가모든 공격 및 주문에 면역",
    ["Heals for $s1."] = "$s1의 생명력 회복",
    ["Inflicts $$s1s$s2 damage to enemies within $$s1a$s2 yards.\nCauses the Little Ooze to merge with other nearby Ooze."] =
    "$$s1a$s2미터 반경 내에 있는 적에게 $$s1s$s2의 피해작은 수액괴물이 주위 수액괴물과 결합하도록 함.",
    ["Inflicts $s1 damage to enemies within $a$s2 yards."] = "$a$s2미터 반경 내에 있는 적에게 $s1의 피해",
    ["Inflicts $$s1s$s2 damage to enemies within $$s1a$s2 yards.\nCauses the Big Ooze to merge with other nearby Ooze."] =
    "$$s1a$s2미터 반경 내에 있는 적에게 $$s1s$s2의 피해큰 수액괴물이 주위 수액괴물과 결합하도록 함.",
    ["Magical spells cast will cause a delayed backlash."] = "주문 시전 시 지연되는 반발력 발생",
    ["Deals $s1 Arcane damage after $d."] = "$d 후 $s1의 비전 피해",
    ["The Ooze sprays a puddle of Green Goo near the target. The Green Goo inflicts $$s1s$s2 damage every $$s3t$s2 sec and decreases move speed by $$s1s$s4%."] =
    "수액괴물이 대상 주변에 녹색 수액 분사매 $$s3t$s2초마다 $$s1s$s2의 피해이동 속도 $$s1s$s4%만큼 감소",
    ["The Green Goo inflicts $$s1s$s2 damage every $t$s2 sec and reduces move speed by $$s1s$s3%."] =
    "녹색 수액이 매 $t$s2초마다 $$s1s$s2의 피해를 입히고 이동 속도를 $$s1s$s3%만큼 감소시킵니다.",
    ["Inflicts $s1 damage every $$s2t$s3 sec.\nReduces move speed by $s4%."] = "매 $$s2t$s3초마다 $s1의 피해이동 속도 $s4%만큼 감소",
    ["Melee, ranged, and spell casting speed increased by $s1%. Health increased by $s2%."] =
    "물리 및 원거리, 주문 시전 속도 $s1%만큼 증가생명력 $s2%만큼 증가",
    ["Inflicts $$s1s$s2 damage to enemies within $$s1a$s2 yards."] = "$$s1a$s2미터 반경 내에 있는 적에게 $$s1s$s2의 피해",
    ["You have Omar's $s1 Man Heroic Seal of Approval!"] = "오마르의 $s1인 영웅 승인 인장 획득!",
    ["The two Little Ooze merge into a Big Ooze!"] = "작은 수액괴물 2마리가 결합하여 큰 수액괴물로 변합니다!",
    ["Quel'Delar pulses with darkness and seems to be pulling you toward the Halls of Reflection in Icecrown Citadel."] =
    "쿠엘델라가 어둠의 힘으로 고동치며 얼음왕관 성채에 있는 투영의 전당으로 당신을 이끕니다.",
    ["Held in the grip of Frostmourne."] = "서리한의 손아귀에 붙잡힘",
    ["Suffering $s1 Frost damage every $t$s2 sec."] = "매 $t$s2초마다 $s1의 냉기 피해",
    ["Undead."] = "불사 상태",
    ["Melee and physical attacks to Sindragosa have a chance to chill you to the bone."] =
    "신드라고사에게 근접 및 물리 공격 시 일정 확률로 사무치는 한기 효과",
    ["Being tracked by Sindragosa's magical orbs."] = "신드라고사의 마법 구슬에게 추적당하는 중",
    ["Damage taken from magical sources increased by $s1%."] = "받는 마법 피해 $s1%만큼 증가",
    ["Pulsing waves of arcane magic every $t$s1 sec."] = "매 $t$s1초마다 비전 마법의 물결 방출",
    ["Frozen to the ground."] = "얼어붙은 땅",
    ["Immune to $s1 debuff."] = "$s1 약화 효과에 면역",
    ["Entombed in ice."] = "얼음 무덤에 갇힘",
    ["Dodge chance increased by $s1%.\nImmune to magic schools."] = "회피율 $s1%만큼 증가마법 계열에 면역",
    ["Analyzing..."] = "분석 중...",
    ["Unable to attack, move or use spells. Immune to all attacks and spells."] = "공격 및 이동, 주문 시전 불가모든 공격 및 주문에 면역",
    ["Is Svalna."] = "스발나인지 확인",
    ["Fixated on the player with Gaseous Bloat.\nMelee attacks cause Expunged Gas which deals damage based on how bloated the player is."] =
    "가스 팽창 효과에 걸린 플레이어에게 몰려듬근접 공격 시 해소된 가스가 발생하며 플레이어가 팽창한 정도에 따라 증가하는 피해 입힘",
    ["Damage done increased by $s1%.\nSpells have no cost and are instant.\nMelee and ranged attack speed increased $s2%."] =
    "공격력 $s1%만큼 증가모든 주문에 마나 및 시전 시간 불필요근접 및 원거리 공격 속도 $s2%만큼 증가",
    ["Damage done increased by $s1%.\nHealth increased by $s2%. \nSpells have no cost and are instant.\nMelee and ranged attack speed increased $s3%."] =
    "공격력 $s1%만큼 증가생명력 $s2%만큼 증가모든 주문에 마나 및 시전 시간 불필요근접 및 원거리 공격 속도 $s3%만큼 증가",
    ["Attack Power increased by $s1."] = "전투력 $s1만큼 증가",
    ["Spell Power increased by $s1."] = "주문력 $s1만큼 증가",
    ["Defense Rating increased by $s1."] = "방어 숙련도 $s1만큼 증가",
    ["Cloaked."] = "은폐 기능 작동 중",
    ["Dealing Frost damage every $t$s1 sec.\nDamage ceases when the target is fully healed."] =
    "매 $t$s1초마다 냉기 피해생명력을 모두 회복해야만 피해가 멈춤",
    ["The Crown Chemical Company guards spotted you!"] = "왕관화학회사 경비병에게 들켰습니다!",
    ["Damage done increased by $s1%. \nSpells have no cost and are instant.\nMelee and ranged attack speed increased $s2%."] =
    "공격력 $s1%만큼 증가모든 주문에 마나 및 시전 시간 불필요근접 및 원거리 공격 속도 $s2%만큼 증가",
    ["You begin to mutate!"] = "변이하기 시작합니다!",
    ["You have been mutated!"] = "돌연변이가 되었습니다!",
    ["Dealing Frost damage to all nearby enemies."] = "주위 모든 적에게 냉기 피해",
    ["Deals $s1 Shadow damage every $t$s2 sec.\nJumps to nearby target when removed or host dies."] =
    "매 $t$s2초마다 $s1의 암흑 피해해제되거나 숙주 사망 시 근처 대상에게 전이",
    ["Throws a vial of Mutated Slime, creating a puddle of slime at the targets location."] =
    "돌연변이 점액이 담긴 약병을 던져 대상 지역에 점액의 웅덩이를 생성합니다.",
    ["Creates a puddle of mutated slime."] = "돌연변이 점액의 웅덩이를 생성합니다.",
    ["The Mutated Slime grows continuously, inflicting $$s1s$s2 damage every $t$s2 sec until it is consumed by a Mutated creature!"] =
    "돌연변이 점액이 점점 자라나, 다른 돌연변이에게 흡수될 때까지 매 $t$s2초마다 $$s1s$s2의 피해를 입힙니다.",
    ["Inflicts $s1 damage to targets in the Slime Puddle."] = "점액 웅덩이 안에 있는 대상에게 $s1의 피해를 입힙니다.",
    ["Professor Putricide begins to peform a wicked experiment on you all!"] =
    "교수 퓨트리사이드가 당신과 동료 모두를 대상으로 사악한 실험을 시작합니다!",
    ["You will be targeted with things that also have the Ooze trait.\nYou are unable to harm Gaseous creatures."] =
    "수액 변수를 얻었습니다! 수액 형질을 얻은 무리와 함께 표적이 되고 가스 몬스터는 공격할 수 없습니다.",
    ["You will be targeted with things that also have the Gas trait.\nYou are also unable to harm Ooze creatures."] =
    "가스 변수를 얻었습니다! 가스 형질을 얻은 무리와 함께 표적이 되고 수액 몬스터는 공격할 수 없습니다.",
    ["Deals $s1 Frost damage after $t$s2 sec.\nMovement speed reduced by $s3%."] = "$t$s2초 후 $s1의 냉기 피해이동 속도 $s3%만큼 감소",
    ["The diseases from the Mutated Abomination is inflicting damage to nearby players!"] =
    "돌연변이 누더기골렘의 질병이 주위 플레이어에게 피해를 입힙니다.",
    ["|cFF$s1AA$s2\"Best in Show\"|r"] = "|cFF$s1AA$s2\"최우수견\"|r",
    ["Inflicts $$s1s$s2 damage to nearby players every $t$s2 sec.\nCuring the disease will revert the player to their form."] =
    "매 $t$s2초마다 주위 플레이어에게 $$s1s$s2의 피해질병이 치유되면 플레이어의 원래 모습으로 돌아감",
    ["Receiving direct heals will cause Corrupted Blood."] = "직접 치유를 받으면 오염된 피 효과를 일으킴",
    ["Incapacitated. Deals $s1 bleed damage every $t$s2 seconds."] = "행동 불가매 $t$s2초마다 $s1의 출혈 피해",
    ["$s1% of damage done to you is dealt to linked source."] = "연결된 대상에게 자신이 입은 피해의 $s1%에 해당하는 피해",
    ["Rooted.\nInflicts $s1 damage every $t$s2 sec.\nWhen the Volatile Ooze reaches you, it will explode for $$s3s$s2 damage, split among all nearby targets."] =
    "이동 불가매 $t$s2초마다 $s1의 피해일촉즉발 수액괴물이 근접해 오면 폭발하여 $$s3s$s2의 피해를 입히고 분열하여 주위 모든 대상에게 퍼짐",
    ["$s1% of damage done to linked source is reflected to you."] = "연결된 대상이 입은 피해의 $s1%에 해당하는 피해",
    ["$$s1s$s2% of damage done to linked source is reflected to you"] = "연결된 대상이 입은 피해의 $$s1s$s2%에 해당하는 피해",
    ["Deals Frost damage to anyone in the way."] = "이동 경로 내의 모든 적에게 냉기 피해",
    ["Deals $s1% of maximum health every $t$s2 sec."] = "매 $t$s2초마다 최대 생명력의 $s1%에 해당하는 피해",
    ["Inflicts $s1 damage shared with nearby targets, knocking them back in all directions!"] =
    "주변에 있는 대상에게 $s1의 피해를 나누어 입히고 사방으로 멀리 밀쳐냅니다.",
    ["Taking periodic Fire damage."] = "주기적인 화염 피해",
    ["You feel disoriented from being forcefully teleported."] = "방향 감각 상실강제로 소환됨",
    ["Movement speed reduced by $s1%.\n\n|cFFFFAA$s2\"Do you think they noticed that?\"|r"] =
    "이동 속도 $s1%만큼 감소|cFFFFAA$s2\"그들이 과연 눈치 챘을까요?\"|r",
    ["Dodge is increased by $s1 rating."] = "회피 숙련도 $s1만큼 증가",
    ["Movemend speed decreased by $s1%.\nInflicts $s2 damage every $t$s3 sec."] = "이동 속도 $s1%만큼 감소매 $t$s3초마다 $s2의 피해",
    ["Deals increasing Shadow damage per second.\nRemoved when target has more than $s1% health."] =
    "매초마다 증가하는 암흑 피해대상의 생명력이 $s1% 이상 회복되면 사라짐",
    ["Writhing in agony."] = "고통의 몸부림",
    ["Hot lips."] = "제 뜨거운 입술을 받아주세요.",
    ["You're mine!"] = "당신은 제 것이에요!",
    ["You're the best!"] = "당신이 최고예요!",
    ["Be mine!"] = "저의 사랑을 받아주세요!",
    ["All yours."] = "당신은 정말 소중한 사람입니다.",
    ["I'll follow you all around Azeroth."] = "이 아제로스 끝까지라도 당신을 따르겠어요.",
    ["I LOVE YOU"] = "당신을 사랑합니다.",
    ["I'm all yours!"] = "제 모든 걸 당신께 드리겠어요.",
    ["Sumons allies to Jaina."] = "아군을 소환합니다.",
    ["Deals $s1 Nature damage per second.\nIncreases Physical damage taken by $s2%."] =
    "매초마다 $s1의 자연 피해받는 물리 피해 $s2%만큼 증가",
    ["$s1% increased damage done."] = "공격력 $s1%만큼 증가",
    ["Absorbs up to $s1 points of healing received."] = "받는 치유량 최대 $s1만큼 흡수",
    ["Inflicts $s1 damage every $t$s2 sec.\nIf the Gas Cloud hits you it will expunge all remaining Gaseous Bloat, inflicting damage to all nearby allies."] =
    "매 $t$s2초마다 $s1의 피해가스 구름에 적중당하면 남은 가스 팽창 효과를 모두 해소하며 주위 모든 적을 공격",
    ["Damage increased by $s1%.\nHealed for $s2% of all damage inflicted."] = "공격력 $s1%만큼 증가입힌 피해의 $s2%에 해당하는 생명력 회복",
    ["The Gas Cloud's attack has expunged all of the gas from the target! Expunged Gas inflicts damage to all enemies based on the number of Gaseous Blight stacks that were remaining on the target when they were attacked."] =
    "가스 구름이 대상을 공격하여 가스를 모두 해소했습니다! 해소된 가스는 모든 적에게 공격받을 당시 대상에 파멸의 역병 가스가 중복된 횟수에 따라 증가하는 피해를 입힙니다.",
    ["Nature and Arcane damage done increased by $s1%."] = "자연 및 비전 계열 공격력 $s1%만큼 증가",
    ["Stone."] = "돌",
    ["Armor reduced by $s1%.\nDeals $s2 Nature damage every $t$s3 sec."] = "방어도 $s1%만큼 감소매 $t$s3초마다 $s2의 자연 피해",
    ["$s1 sec reduced cast time on next Holy Light."] = "다음 성스러운 빛 주문의 시전 시간 $s1초만큼 감소",
    ["Flight."] = "비행",
    ["Reflecting harmful spells.\nCannot be interrupted.\nAbsorbs up to $s1 damage before breaking."] =
