    ["Increased spell haste by $s1%."] = "주문 가속 $s1%만큼 증가",
    ["Healing damage every $t$s1 sec."] = "매 $t$s1초마다 생명력 회복",
    ["$$s1s$s2% of damage done to you is dealt to the linked source."] = "연결된 대상에게 자신이 입은 피해의 $$s1s$s2%에 해당하는 피해",
    ["$$s1s$s2% of damage done to linked source is reflected to you."] = "연결된 대상이 입은 피해의 $$s1s$s2%에 해당하는 피해",
    ["Consumes mana to repair any damage sustained."] = "마나를 소비하여 손실된 생명력 회복",
    ["Slows casting and attack speed by $s1%."] = "주문 시전 및 공격 속도 $s1%만큼 저하",
    ["Damage increased by $$s1s$s2%.\nHealed for $$s3s$s4% of all damage inflicted.\nAttacks cause no threat."] =
    "공격력 $$s1s$s2%만큼 증가입힌 피해의 $$s3s$s4%에 해당하는 생명력 회복공격 시 위협 수준 발생하지 않음",
    ["Damage increased by $s1%.\nHealed for $s2% of all damage inflicted.\nAttacks cause no threat."] =
    "공격력 $s1%만큼 증가입힌 피해의 $s2%에 해당하는 생명력 회복공격 시 위협 수준 발생하지 않음",
    ["Regenerating $s1 Mana every $t$s2 sec.\nIncreases Damage done by $s3%.\nIncreases Healing done by $s4%."] =
    "매 $t$s2초마다 $s1의 마나 회복공격력 $s3%만큼 증가치유량 $s4%만큼 증가",
    ["You must feed! Your will is fading..."] = "마셔야 합니다! 의지가 사라져갑니다....",
    ["Increases damage you and your pet deal."] = "사냥꾼과 야수의 공격력 증가",
    ["Transformed into a powerful zombie."] = "강력한 좀비로 변신함.",
    ["Spells empowered to deal area damage.\nImmune to interrupt effects."] = "강화된 주문으로 광역 공격주문 방해 효과에 면역",
    ["Stunned.\nRemoved when fully healed."] = "기절함. 생명력 모두 회복 시 제거됨",
    ["The Plague inflicts increasing damage every $t$s1 sec.\nIf you get too near a friendly target, you will transfer the Plague to them."] =
    "매 $t$s1초마다 역병 피해 증가아군 대상이 근접해 있으면 역병 전염",
    ["Charmed.\nIncreases damage done by $s1%.\nHealth increased by $$s2s$s3%.\nIncreases healing done by $$s2s$s4%."] =
    "현혹됨공격력 $s1%만큼 증가생명력 $$s2s$s3%만큼 증가주문 치유량 $$s2s$s4%만큼 증가",
    ["Reduced damage taken."] = "받는 피해 감소",
    ["Deals $s1 damage to the target, granting them the Essence of the Blood Queen. Biting a friendly unit will sate your need for blood. Cannot be used on existing Vampires."] =
    "대상에게 $s1의 피해를 입히고 피의 여왕의 정수를 주입합니다. 아군을 물어뜯으면 피의 갈증이 해소됩니다. 같은 흡혈귀에게는 사용할 수 없습니다.",
    ["Damage and healing done increased by $s1%.\nAttacks heal caster."] = "공격력 및 치유량 $s1%만큼 증가치유 주문 시전자 공격",
    ["The Darkfallen Orb empowers Valanar, granting him more formidable abilities."] =
    "암흑사도의 보주에서 힘을 얻은 발라나르의 능력이 더욱 강력해집니다.",
    ["Increases damage taken from Unbound Plague by $s1%."] = "고삐 풀린 역병의 피해 $s1%만큼 증가",
    ["Unbound Blight Bounce Protection"] = "고삐 풀린 역병 튀어오름 보호",
    ["Attack speed increased by $s%."] = "공격 속도 $s%만큼 증가",
    ["Magical damage taken increased by $s1%."] = "받는 마법 피해 $s1%만큼 증가",
    ["The Darkfallen Orb empowers Keleseth, granting him more formidable abilities."] =
    "암흑사도의 보주에서 힘을 얻은 켈레세스의 능력이 더욱 강력해집니다.",
    ["The Darkfallen Orb empowers Taldaram, granting him more formidable abilities."] =
    "암흑사도의 보주에서 힘을 얻은 탈다람의 능력이 더욱 강력해집니다.",
    ["Inflicts $$s1s$s2 Shadow damage every $t$s2 seconds."] = "매 $t$s2초마다 $$s1s$s2의 암흑 피해",
    ["Increases the power of Shroud of Sorrow by $s1%."] = "슬픔의 수의의 힘 $s1%만큼 증가",
    ["You abandoned a dungeon and must wait before using the Dungeon Finder again."] =
    "던전을 포기했으므로, 던전 찾기를 재사용하려면 기다려야 합니다.",
    ["Wearing a Lovely Rose."] = "아름다운 장미 꽂음",
    ["You feel sightly larger... \n\n|cFFFFAA$s1\"Don't mind the color.\"|r"] =
    "약간 커진 것 같습니다...|cFFFFAA$s1\"색깔은 신경쓰지 마세요.\"|r",
    ["Cannot attack or cast spells.\nMovement speed reduced by $s1%."] = "마법 시전 및 공격 불가이동 속도 $s1%만큼 감소",
    ["Healing spells increased by $s1%."] = "치유 주문의 효과 $s1%만큼 증가",
    ["Describe Shadow's Edge Aura"] = "어둠의 칼날도끼 오라 묘사",
    ["Upon dying, this creature's soul will be claimed by Shadow's Edge."] = "사망 시 영혼이 어둠의 칼날도끼에 귀속됩니다.",
    ["Cast time of Frostbolt and Frostfire Bolt reduced by $s1 sec."] = "얼음 화살과 얼음불꽃 화살의 시전 시간 $s1만큼 단축",
    ["Damage done increased by $s1%.\nAttack and casting speeds increased by $s2%."] =
    "공격력 $s1%만큼 증가공격 및 시전 속도 $s2%만큼 증가",
    ["This unit gains experience in combat as it fights, allowing it to become more powerful over time."] =
    "전투 시 경험치를 얻어 시간이 지날수록 더욱 강해집니다.",
    ["Your actions generate $s1% less threat."] = "생성하는 위협 수준 $s1%만큼 감소",
    ["Nearly impervious to magical damage."] = "마법 공격에 거의 면역",
    ["Nearly impervious to physical damage."] = "물리 공격에 거의 면역",
    ["Ability cooldowns increased by $s1 seconds."] = "기술의 재사용 대기시간 $s1만큼 증가",
    ["Immune to movement and control impairing effects."] = "이동 불가 및 제어 방해 효과에 면역",
    ["Professor Putricide throws Gas Bombs around him, the Gas Bomb deals $$s1s$s2 damage every $$s1t$s2 sec and explodes for $$s3s$s2 damage after $$s1d."] =
    "교수 퓨트리사이드가 자신의 주변에 가스탄을 투척하여 매 $$s1t$s2초마다 $$s1s$s2의 피해를 입히고 $$s1d 후 폭발하여 $$s3s$s2의 피해를 입힙니다.",
    ["Taking $s1 additional damage every $t$s2 sec."] = "매 $t$s2초마다 $s1의 추가 피해",
    ["A swarming mass of shadows accumulates beneath you."] = "발밑에 거대한 어둠이 쌓입니다.",
    ["Inflicts $$s1s$s2 Shadow damage every $$s1t$s2 sec.\nShadows accumulate beneath you every $t$s2 seconds."] =
    "매 $$s1t$s2초마다 $$s1s$s2의 피해발밑에 매 $t$s2초마다 어둠이 쌓임",
    ["Shadows accumulate beneath the target."] = "대상의 발밑에 어둠이 쌓입니다.",
    ["Dealing Frost damage to nearby enemies."] = "주위 적에게 냉기 피해",
    ["Channelling a Frost Orb."] = "얼어붙은 구슬에 정신 집중",
    ["Swarming shadows inflict $s1 damage every $t$s2 sec.\nShadows accumulate beneath you every $t$s2 seconds."] =
    "모여드는 어둠이 매 $t$s2초마다 $s1의 피해 입힘발밑에 매 $t$s2초마다 어둠이 쌓임",
    ["You recently queued for a random dungeon and must wait before using the Dungeon Finder again."] =
    "최근 무작위 던전 대기열에 등록했으므로 던전 찾기를 재사용하려면 기다려야 합니다.",
    ["Deals growing Shadow damage to you and nearby non-linked allies. This effect expires when all linked targets are within $s1 yards of each other."] =
    "자신과 주위의 연결되지 않은 아군에게 점차 증가하는 암흑 피해를 입힙니다. 이 효과는 연결된 대상들 간의 거리가 $s1미터 이하일 때 사라집니다.",
    ["A whelp is focusing fire upon you."] = "새끼용의 집중 화염 공격을 받는 중",
    ["Armor penetration rating increased by $s1."] = "방어구 관통력 $s1만큼 증가",
    ["Mote of Anger."] = "분노의 티끌",
    ["Dealing $s1% of maximum health every second.\nStunned."] = "매초마다 최대 생명력의 $s1%에 해당하는 피해기절함.",
    ["Disguised as a CPS package-runner. Go go go!"] = "왕관 택배 서비스 배달원으로 변장했습니다. 빠르게 이동!",
    ["Carrying a crate of Crown Chemical Co. contraband."] = "왕관화학회사 밀수품 상자 운반",
    ["Inflicts $$s1s$s2 Divine damage every $t$s2 sec."] = "매 $t$s2초마다 $$s1s$s2의 피해",
    ["Granted $s1 strength by the form of the Taunka."] = "타운카의 모습이 되어 힘 $s1만큼 증가",
    ["Granted $s1 agility by the form of the Vrykul."] = "브리쿨의 모습이 되어 민첩성 $s1만큼 증가",
    ["Granted $s1 attack power by the form of the Taunka."] = "타운카의 모습이 되어 전투력 $s1만큼 증가",
    ["Granted $s1 armor penetration rating by the form of the Iron Dwarves."] = "무쇠 드워프의 모습이 되어 방어구 관통력 $s1만큼 증가",
    ["Granted $s1 critical strike rating by the form of the Iron Dwarves."] = "무쇠 드워프의 모습이 되어 치명타 및 주문 극대화 적중도 $s1만큼 증가",
    ["Granted $s1 haste rating by the form of the Vrykul."] = "브리쿨의 모습이 되어 가속도 $s1만큼 증가",
    ["Phew! The smell is overpowering..."] = "후! 냄새가 코를 찌릅니다...",
    ["Shadow's Edge seethes with Unholy power and is ready to claim Putricide's soul."] =
    "어둠의 칼날도끼가 부정의 힘으로 충만하여 퓨트리사이드의 영혼을 거둘 준비가 되었습니다.",
    ["Fire damage taken is increased by $m$s1%."] = "받는 화염 피해 $m$s1%만큼 증가",
    ["Granted $s1 strength by the form of the Taunka"] = "타운카의 모습이 되어 힘 $s1만큼 증가",
    ["Increases stamina by $s1."] = "체력 $s1만큼 증가",
    ["Inflicts damage every $$s1t$s2 sec.\nReduces move speed by $s3%."] = "매 $$s1t$s2초마다 피해이동 속도 $s3%만큼 감소",
    ["Focusing a machine gun on the enemy target."] = "기관총으로 적을 조준합니다.",
    ["Increases spell power by $$s1s$s2 every $t$s2 sec."] = "매 $t$s2초마다 주문력 $$s1s$s2만큼 증가",
    ["Increases Physical damage dealt by $s1%.\nIncreases attack speed by $s2%.\nAttacks cause the caster to become mutated further."] =
    "물리 공격력 $s1%만큼 증가공격 속도 $s2%만큼 증가공격할수록 돌연변이를 일으킴",
    ["Stunned.\nImmune."] = "기절함.면역",
    ["You are dazed by the tear gas, preventing you from moving!"] = "최루 가스로 멍해져서 움직일 수 없습니다!",
    ["Throws a vial of tear gas, stunning all targets in the room!"] = "최루 가스 약병을 던져 실내에 있는 모든 대상을 기절시킵니다!",
    ["Professor Putricide is rifling through the lab table, searching for a powerful potion!"] =
    "교수 퓨트리사이드가 실험실 탁자 사이를 총알처럼 움직이며 강력한 물약을 찾고 있습니다!",
    ["Arane, Fire, Frost, Nature, and Shadow resistance increased by $s1."] = "비전, 화염, 냉기, 자연, 암흑 주문에 대한 저항력 $s1만큼 증가",
    ["You are running out of air inside the Ice Tomb!"] = "얼음 무덤 안의 공기가 희박해집니다!",
    ["Professor Putricide starts to drink ever potion on the table!"] = "교수 퓨트리사이드가 탁자 위의 물약을 마십니다!",
    ["Searching Stormwind Bank for Snivel Rustrocket."] = "스톰윈드 은행에서 스니블 러스트로켓을 찾고 있습니다.",
    ["Stunned by Snivel Rustrocket's portable rocket launcher."] = "스니블 러스트로켓의 휴대용 로켓 발사기때문에 기절했습니다.",
    ["Deals $s1 damage to the target, granting them the Essence of the Vampyr Queen. Biting a friendly unit will sate your need for blood. Cannot be used on existing Vampires."] =
    "대상에게 $s1의 피해를 입히고 흡혈 여왕의 정수를 주입합니다.",
    ["Melee attacks heal the attacker for $$s1s$s2."] = "근접 공격 시 공격자의 생명력이 $$s1s$s2만큼 회복됩니다.",
    ["Searching the auction house for Snivel Rustrocket."] = "경매장에서 스니블 러스트로켓을 찾고 있습니다.",
    ["Snivel Rustrocket has blinded you while he makes his escape."] = "스니블 러스트로켓이 탈출하는 동안 당신의 눈을 멀게 했습니다.",
    ["Searching the barber shop for Snivel Rustrocket."] = "미용실에서 스니블 러스트로켓을 찾고 있습니다.",
    ["Searching the Orgrimmar bank for Snivel Rustrocket."] = "오그리마 은행에서 스니블 러스트로켓을 찾고 있습니다.",
    ["Summons a maelstrom of whirling Bloodbolts."] = "핏빛 화살의 소용돌이를 소환합니다.",
    ["Focusing on an enemy target."] = "적 조준 중",
    ["Deals $s1 damage every $t$s2 sec. and reduces movement speed by $s3%."] = "매 $t$s2초마다 $s1의 화염 피해이동 속도 $s3%만큼 감소",
    ["Shadow damage taken is reduced by $s1%."] = "받는 암흑 피해 $s1%만큼 감소",
    ["Orange"] = "주황색",
    ["Healing nearby friends for $s1 every sec."] = "주위 아군의 생명력 매초마다 $s1만큼 회복",
    ["Increased strength by $s1 and healing received by $s2."] = "힘 $s1만큼 증가받는 치유 효과 $s2만큼 증가",
    ["Melee attacks deal an additional $s1% damage as shadow damage."] = "근접 공격 시 입힌 피해의 $s1%에 해당하는 추가 암흑 피해",
    ["Restores $s1 energy every $t$s2 seconds."] = "매 $t$s2초마다 $s1의 기력 회복",
    ["Restores $s1 rage every $s2 seconds."] = "매 $s2초마다 $s1의 분노 회복",
    ["Restores $s1 runic power every $s2 seconds."] = "매 $s2초마다 $s1의 룬 마력 회복",
    ["Professor Putricide starts to drink every potion on the table!"] = "교수 퓨트리사이드가 탁자 위의 물약을 모두 마십니다!",
    ["Suffering from a broken heart."] = "실연의 고통",
    ["The nearest target resonates with shadow, suffering $$s1s$s2 damage and reducing Shadow damage taken from all sources by $$s1s$s3% for $$s1d."] =
    "가장 가까운 대상은 암흑 공명을 일으켜 $$s1s$s2의 피해를 입고 $$s1d 동안 모든 공격으로 입는 암흑 피해가 $$s1s$s3%만큼 감소합니다.",
    ["Regenerating $s1 Mana every $t$s2 sec.\nIncreases Damage done by $$s3s$s4%.\nIncreases Healing done by $s5%.\nDeals $$s3s$s2 Nature damage per second."] =
    "매 $t$s2초마다 $s1의 마나 회복공격력 $$s3s$s4%만큼 증가치유량 $s5%만큼 증가매초마다 $$s3s$s2의 자연 피해",
    ["Absorbs up to $s1 points of healing."] = "받는 치유량 최대 $s1만큼 흡수",
    ["Healing nearby allies for $s1% of their maximum health every $t$s2 sec."] =
    "주위 아군의 생명력 매 $t$s2초마다 최대 생명력의 $s1%만큼 회복",
    ["Health increased by $s1%.\nDamage increase by $s2%."] = "생명력 $s1%만큼 증가공격력 $s2%만큼 증가",
    ["Stunned.\nBeing attacked."] = "기절함. 공격받는 중",
    ["$s1 Chaos damage inflicted every $t$s2 sec."] = "매 $t$s2초마다 $s1의 혼돈 피해",
    ["Incapacitated and reeking."] = "행동 불가냄새남",
    ["Attacks have a chance to apply Frostbite!"] = "공격 시 일정 확률로 동상을 일으킵니다!",
    ["Inflicts $s1 Frost damage every $t$s2 sec.\nReduces movement speed by $s3%."] =
    "매 $t$s2초마다 $s1의 냉기 피해이동 속도 $s3%만큼 감소",
    ["Increases Frost damage taken by $s1%."] = "받는 냉기 피해 $s1%만큼 증가",
    ["The Kinetic Bomb is highly unstable and will dissipate harmlessly after $d if it fails to detonate on a hard surface."] =
    "요동치는 폭탄은 매우 불안정하며 단단한 표면 위에서 폭발하지 않으면 $d 후 사라집니다.",
    ["The Frozen Orb inflicts $$s1s$s2 damage every $t$s2 sec to enemies within $$s1a$s2 yards."] =
    "얼어붙은 구슬이 $$s1a$s2미터 반경 내의 적에게 매 $t$s2초마다 $$s1s$s2의 피해를 입힙니다.",
    ["Inflicts $s1 damage to enemies within $a$s2 yards of the Frozen Orb."] =
    "얼어붙은 구슬로부터 $a$s2미터 반경 내의 적에게 $s1의 피해를 입힙니다.",
    ["Creates a Frozen Orb at a nearby location."] = "주변에 얼어붙은 구슬을 만듭니다.",
    ["Feeds Shadow's Edge with the blood of its owner. Inflicts $s1 damage per second and weakens the victim, reducing their damage dealt by $s2%."] =
    "어둠의 칼날도끼에게 주인의 피를 맛보게 합니다. 매초마다 $s1의 피해를 입히고 대상을 약화시켜 공격력을 $s2%만큼 감소시킵니다.",
    ["Increases Physical damage by $s1%."] = "물리 공격력 $s1%만큼 증가",
    ["Lingering traces of Festergut's blight."] = "구린속의 역병이 남긴 사라지지 않는 흔적",
    ["Lingering traces of Rotface's blight."] = "썩은얼굴의 역병이 남긴 사라지지 않는 흔적",
    ["Shadow's Edge has slaked its bloodthirst and is ready to feast upon Lana'thel's soul."] =
    "어둠의 칼날도끼에 서린 피의 갈증이 해소되어, 이제 라나텔의 영혼으로 배를 채울 준비가 되었습니다.",
    ["Damage inflicted by this creature infuses Deathbringer Saurfang with Blood Power."] =
    "피해를 입힐 때마다 죽음의 인도자 사울팽에게 피의 힘이 주입됩니다.",
    ["Damage inflicted with abilities and summoned creatures generates Blood Power."] =
    "사울팽이 자신의 기술과 소환한 생물로 피해를 입혀 피의 힘을 얻습니다.",
    ["Increases damage dealt by $s1%.\nCauses a Gastric Explosion at $s2 stacks."] = "공격력 $s1%만큼 증가$s2회 중복 시 위 폭발",
    ["Increases damage done by $s1%, healing done by $s2%, and health by $s3% whenever you use the Dungeon tool to find other players for your group."] =
    "던전 도구를 이용하여 파티원 모집 시 공격력 $s1%만큼, 치유량 $s2%만큼, 생명력 $s3%만큼 증가",
    ["Linked Aura"] = "연결된 오라",
    ["Cannot be affected by Guardian Spirit."] = "수호 영혼에 영향받지 않음",
    ["Shadow's Edge pulses with Frost energy and is prepared for Sindragosa's demise."] =
    "냉기의 힘에 공명하는  어둠의 칼날도끼가 신드라고사를 처단할 준비가 되었습니다.",
    ["Shadow's Edge absorbs Sindragosa's frost breath, making it painful to wield. Inflicts $s1 damage per second."] =
    "어둠의 칼날도끼가 신드라고사의 냉기 숨결을 흡수하여 사용자가 고통을 느끼도록 합니다. 매초마다 $s1의 피해를 입힙니다.",
    ["$$s1s$s2 Physical damage inflicted when Saurfang performs a melee attack. Heals Saurfang for $$s3s$s2% of his total health on death."] =
    "사울팽이 근접 공격 시 $$s1s$s2의 물리 피해사망 시 사울팽은 전체 생명력의 $$s3s$s2% 회복",
    ["Damage taken increased by $s1%.\nDamage dealt reduced by $s2%."] = "받는 피해 $s1%만큼 증가공격력 $s2%만큼 감소",
    ["Cannot resurrect."] = "부활 불가",
    ["Inflicts Corrupted Touch every $t$s1 sec."] = "매 $t$s1초마다 부패한 손길의 효과",
    ["Linked Aura - Should be same stack as Primary Aura and go away when Primary Aura goes away."] = "시험용",
    ["Primary Aura"] = "기본 오라",
    ["Dealing $s1 Shadow damage every $t$s2 sec. \nDeals the remaining damage to nearby allies if dispelled."] =
    "매 $t$s2초마다 $s1의 암흑 피해무효화되면 주위 아군에게 잔여 피해",
    ["Saurfang grows $s1% larger for each point of Blood Power he has."] = "사울팽이 가진 피의 힘이 증가할 때마다 몸집이 $s1%만큼 커집니다.",
    ["Saurfang grows $s1% larger and deals $s2% more damage for each point of Blood Power he has."] =
    "사울팽이 가진 피의 힘이 증가할 때마다 몸집이 $s1%만큼 커지고 공격력이 $s2%만큼 증가합니다.",
    ["Damage and healing dealt reduced by $s1%."] = "공격력 및 치유량 $s1%만큼 감소",
    ["Mirror's Name"] = "이름 복제",
    ["$$s1s$s2 health leeched when damaged by Saurfang's melee attacks. Saurfang is healed for many times the amount leeched."] =
    "사울팽이 근접 공격 시 대상의 생명력을 $$s1s$s2만큼 흡수하여 흡수량의 수 배에 해당하는 생명력을 회복합니다.",
    ["Dodge chance reduced by $s1%."] = "회피율 $s1%만큼 감소",
    ["Infused with life energy."] = "생명의 힘 주입됨",
    ["Stunned for $$s1d. if not dispelled."] = "해제되지 않으면 $$s1d 동안 기절함.",
    ["Horrified.\n$s1 Shadow damage inflicted every $t$s2 sec."] = "극심한 공포에 휩싸임매 $t$s2초마다 $s1의 암흑 피해",
    ["You have been targeted by the Gas Cloud's Gaseous Bloat!"] = "가스 구름이 일으키는 가스 팽창의 대상이 되었습니다.",
    ["Inflicts damage every $t$s1 sec."] = "매 $t$s1초마다 피해",
    ["Inflicts Shadow damage."] = "암흑 피해",
    ["Inflicts damage to targets in the Mutated Slime."] = "돌연변이 점액 안에 있는 대상을 공격합니다.",
    ["Life energies preserve Sindragosa's spirit."] = "생명의 힘으로 신드라고사의 영혼이 보존됩니다.",
    ["Your soul is being consumed by Frostmourne."] = "서리한에 영혼을 흡수당하고 있습니다.",
    ["Increases all damage dealt by $s1%."] = "모든 공격력 $s1%만큼 증가",
    ["Damage from area of effect attacks is reduced by $s1% and damage from Diseases is reduced by $s2%."] =
    "광역 공격으로 받는 피해 $s1%만큼 감소질병으로 받는 피해 $s2%만큼 감소",
    ["The Mutated Plague spreads to Professor Putricide, healing him for $s1 for each stack of Mutated Plague that was on the target."] =
    "돌연변이 역병이 교수 퓨트리사이드에게 퍼져 대상에게 걸린 돌연변이 역병 하나당 $s1의 생명력을 회복시킵니다.",
    ["Physical Damage done increased by $s1%."] = "물리 공격력 $s1%만큼 증가",
    ["Infects allies within $s1 yards upon expiration, also dealing $$s2s$s3 Nature damage.\nIf the Plague does not find a new host, it |cFFFF$s4KILLS|r you."] =
    "지속시간이 끝나면 $s1미터 내의 아군에게 전염되고 $$s2s$s3의 자연 피해새로운 숙주를 찾지 못하면 당신은 |cFFFF$s4사망|r",
    ["Protects against reinfection with the Death Plague."] = "죽음의 역병에 다시 감염되지 않음",
    ["Enemies who move will be encased in a prison of Shadow energy that inflicts increasing Shadow damage for every second of movement."] =
    "움직이는 적을 암흑 에너지로 가두어 이동 시 매초마다 증가하는 암흑 피해를 입힙니다.",
    ["Moving inflicts $s1 Shadow damage."] = "이동 시 $s1의 암흑 피해",
    ["Transformed into one of Yorg Stormheart's subjects."] = "요르그 스톰하트의 일족으로 변신 중",
    ["Suffused with the Light."] = "빛에 싸임",
    ["The Ancient Crystal has imbued you with elemental abilities to use against Twilight's Hammer elemental servants."] =
    "고대 수정에서 정기의 능력를 받아 황혼의 망치단 하수인을 공격할 수 있습니다.",
    ["Your soul is being consumed by Frostmourne.\nDeals $s1 Shadow damage per second."] =
    "서리한에 영혼을 흡수당하고 있습니다.매초마다 $s1의 암흑 피해",
    ["Health increased by $s1%.\nHealing and absorption effects increased by $s2%.\nDamage dealt increased by $s3%."] =
    "생명력 $s1%만큼 증가치유량 및 피해 흡수량 효과 $s2%만큼 증가공격력 $s3%만큼 증가",
    ["Deliver this new recruit to Captain Tread Sparknozzle in this time or the gnome will lose interest!"] =
    "이 노움 신병을 시간 안에 대장 트레드 스파크노즐에게 데려가지 않으면 노움이 곧 흥미를 잃을 겁니다!",
    ["Increases physical damage dealt by $s1%.\nStack increases each time Nectrotic Plague jumps."] =
    "물리 공격력 $s1%만큼 증가괴저 역병 전이 시마다 중복되어 효과 증가",
    ["The elements have granted you water walking, increased health and increased health regeneration."] =
    "정령의 축복으로 수면 보행 가능생명력 및 생명력 회복 속도 증가",
    ["Disguised as a doomsday cult recruit."] = "파멸의 이교도로 변장",
    ["Unable to be slowed by more than $s1%."] = "$s1% 이상 느려지지 않음",
    ["Your spells treat the target as if it were Frozen. $s1 charges;."] = "다음 $s1회의 주문은 얼어붙은 대상을 공격한 것과 같은 효과",
    ["Being tracked by Saviana's fiery orbs."] = "사비아나의 불타오르는 구체에 추적당하는 중",
    ["Engulfed in a blazing conflagration!"] = "거대한 불길에 휩싸였습니다!",
    ["You are equipped with a parachute."] = "낙하산을 장착했습니다.",
    ["Wearing a large board emblazoned with a message about the impending end of the world."] =
    "세상의 종말이 임박했음을 알리는 문구가 새겨진 대형 판자 착용",
    ["For Gnomeregan!"] = "놈리건을 위하여!",
    ["Weakens you and nearby allies every $t$s1 sec, reducing damage and healing done by $$s2s$s1% per application."] =
    "매 $t$s1초마다 자신과 주변 아군 약화매 효과마다 공격력 및 치유량 $$s2s$s1%만큼 감소",
    ["When the \"Doc\" is on the clock your health won't drop."] = "의사 선생님이 계시는 동안 생명력 걱정은 없습니다.",
    ["Periodically inflicts damage."] = "주기적 피해",
    ["Causes $s1 Fire damage and generates a Combustion charge every $t$s2 sec.\nWhen removed, causes an explosion proportional to the number of charges present."] =
    "매 $t$s2초마다 $s1의 화염 피해 및 발화 효과 축적제거 시 축적된 징표 수에 비례하여 규모가 증가하는 폭발 발생",
    ["Increases the potential energy unleashed when Fiery Combustion is removed."] = "맹렬한 발화 제거 시 방출되는 에너지 증가",
    ["Like Drill Sergeant Steamcrank said, \"The most important part of battle is how you celebrate a good, hard earned victory.\""] =
    "훈련교관 스팀크랭크는 이렇게 말했습니다. \"전투에서 가장 중요한 것은, 힘들게 얻은 값진 승리를 축하하는 일이다.\"",
    ["Causes $s1 Shadow damage every $t$s2 sec.\nGenerates a Consumption charge every $t$s2 sec.\nWhen removed, causes an explosion proportional to the number of charges present."] =
    "매 $t$s2초마다 $s1의 암흑 피해매 $t$s2초마다 소진의 징표 축적제거 시 축적된 징표 수에 비례하여 규모가 증가하는 폭발 발생",
    ["Increases the potential energy unleashed when Soul Consumption is removed."] = "영혼 소진 제거 시 방출되는 에너지 증가",
    ["Covered in paint. Washes off in water."] = "물감으로 뒤덮임물로 씻으세요.",
    ["Shadows and mists swirl around you...."] = "안개와 어둠이 주위에 소용돌이칩니다...",
    ["Deals and receives normal damage."] = "일반 공격 및 피해",
    ["Damage dealt increased by $s1%.\nDamage taken increased by $s2%."] = "공격력 $s1%만큼 증가받는 피해 $s2%만큼 증가",
    ["Damage dealt reduced by $s1%.\nDamage taken reduced by $s2%."] = "공격력 $s1%만큼 감소받는 피해 $s2%만큼 감소",
    ["A cosmetic overcloak."] = "장식용 덮개망토",
    ["Dat be some powerful voodoo!  Your attacks are stronger and you are more energized.  For the Darkspear!"] =
    "강력한 부두 주문입니다! 활기가 충만하여 더욱 강력한 공격을 할 수 있습니다! 검은창을 위해!",
    ["Chilled by a Frigid Frostling."] = "꼬마 서리 정령 덕분에 추워졌습니다.",
    ["Transformed into a heroic statue. Incapacited while on the pedestal."] = "영웅의 조각상으로 변신 중단상 위에서는 행동 불가",
    ["Deliver this new recruit to Champion Uru'zin in this time or the troll will lose interest!"] =
    "시간 안에 트롤 신병을 용사 우루진에게 데려가지 않으면 전의를 상실할 겁니다!",
    ["No living ting can make its way trough dis barrier!"] = "이 보호막은 아무도 뚫을 수 없다!",
    ["Dealing $$s1s$s2% of weapon damage to enemies in a frontal cone every $t$s2 sec."] =
    "전방의 적에게 매 $t$s2초마다 무기 공격력의 $$s1s$s2%에 해당하는 피해",
    ["The Spirit of the Tiger has granted you a new form and new abilities. (Only works in Sen'jin Village, the Darkspear Strand, and the Echo Isles)"] =
    "호랑이의 혼이 깃들어 새로운 형상과 능력 획득센진 마을, 검은창 해안, 메아리 섬에서만 효과 있음",
    ["Attack speed reduced."] = "공격 속도 감소",
    ["Inflicts $s1 damage every $t$s2 sec.\nMovement speed reduced by $s3%."] = "매 $t$s2초마다 $s1의 피해이동 속도 $s3%만큼 감소",
    ["Attack and casting speed reduced by $s1%."] = "공격 및 시전 속도 $s1%만큼 감소",
    ["The bones haunt you."] = "해골에게 쫓기는 중",
    ["Damage increased by $$s1s$s2% for each ally within $$s3A$s2 yards."] =
    "$$s3A$s2미터 반경 내에 있는 아군 한 명당 공격력 $$s1s$s2%씩 증가",
    ["Ranged attack power increased by $s1."] = "원거리 전투력 $s1만큼 증가",
    ["All damage increased by $s1%."] = "모든 공격력 $s1%만큼 증가",
    ["Bwonsamdi last act was to boot you off the Echo Isles."] = "브원삼디가 마지막으로 한 일은 당신을 메아리 섬에서 내쫓는 일이었습니다.",
    ["Each time your direct healing spells heal a target you cause the target of your heal to heal themselves and friends within $$s1a$s2 yards for $$s1s$s2 each sec for $$s1d."] =
    "직접 치유 주문으로 대상을 치유할 때마다 $$s1d 동안 대상과 그로부터 $$s1a$s2미터 반경 내에 있는 아군의 생명력이 매초마다 $$s1s$s2만큼 회복됩니다.",
    ["Transformed into Gnomeregan Infantry."] = "놈리건 보병으로 모습이 바뀝니다.",
    ["Transformed into a Darkspear Warrior."] = "검은창부족 전사로 모습이 바뀝니다.",
    ["Flight speed increased by $s1%.  A new fantastic point of view!"] = "비행 속도 $s1%만큼 증가환상적인 광경이에요!",
    ["Transformed into a heroic statue."] = "영웅의 조각상으로 변신",
    ["Suffering $s1 Fire damage every $t$s2 sec."] = "매 $t$s2초마다 $s1의 화염 피해",
    ["Deals $$s1s$s2 Fire damage every $t$s2 sec to all enemies within $$s1a$s2 yards.\nIncreases health and damage of all nearby Living Embers."] =
    "주위 $$s1a$s2미터 안의 적에게 매 $t$s2초마다 $$s1s$s2의 화염 피해가까운 곳의 모든 살아있는 불꽃의 생명력과 공격력 증가",
}
